const noticias = $input.all();

const noticiasOrganizadas = noticias.map((item, index) => {
  const noticia = item.json;

  return {
    id: index + 1,
    titulo: noticia.titulo || noticia.title || "",
    data: noticia.isoDate || noticia.pubDate || "",
    fonte: noticia.creator || noticia.source || "",
    link: noticia.link || noticia.Link || "",
    resumo: noticia.conteúdoFragmento ||
            noticia.contentSnippet ||
            noticia.content ||
            ""
  };
});

return [
  {
    json: {
      projeto: "ViceScope",
      idioma: "en-US",
      quantidade_noticias: noticiasOrganizadas.length,
      noticias: noticiasOrganizadas
    }
  }
];

const noticias = $input.all();

const palavrasChave = [
  /\bgta[\s-]?(?:6|vi)\b/i,
  /\bgrand theft auto[\s-]?(?:6|vi)\b/i
];

const filtradas = noticias.filter(item => {
  const titulo = item.json.title || "";

  return palavrasChave.some(regex => regex.test(titulo));
});

return filtradas.map(item => ({
  json: {
    titulo: item.json.title,
    link: item.json.link,
    data: item.json.isoDate || item.json.pubDate,
    autor: item.json.creator || "",
    fonte: "GameSpot",
    conteudo: item.json.contentSnippet || "",
    status_verificacao: "PENDENTE"
  }
}));

/**
 * ==========================================================
 * VICESCOPE | NEWS INTELLIGENCE CLASSIFIER V4.1
 * ==========================================================
 *
 * Classificador editorial para notícias de GTA VI.
 *
 * FUNÇÕES:
 * - Validar notícias recebidas pelo n8n
 * - Preservar e normalizar links
 * - Identificar rumores e vazamentos
 * - Detectar possíveis anúncios oficiais
 * - Identificar notícias duplicadas no mesmo lote
 * - Avaliar qualidade dos dados
 * - Calcular prioridade editorial
 * - Identificar notícias antigas
 * - Preparar dados para verificação independente
 * - Bloquear produção e publicação sem aprovação
 *
 * IMPORTANTE:
 * Este código NÃO verifica a veracidade dos fatos.
 * Nenhuma notícia é aprovada automaticamente.
 * ==========================================================
 */

const CONFIG = {
  projeto: "ViceScope",
  versao: "4.1",
  idioma: "en-US",

  maxIdadeHoras: 168,

  palavrasGTA: [
    /\bgta[\s-]?(?:6|vi)\b/i,
    /\bgrand theft auto[\s-]?(?:6|vi)\b/i
  ],

  termosVazamento: [
    /\bleak(?:ed|s|er|ers|ing)?\b/i,
    /\brumou?rs?\b/i,
    /\bunconfirmed\b/i,
    /\balleged(?:ly)?\b/i,
    /\bsupposed(?:ly)?\b/i,
    /\bspeculat(?:ion|ive|e|es|ed|ing)\b/i
  ],

  termosOficiais: [
    /\bofficial(?:ly)?\b/i,
    /\bannounc(?:e|es|ed|ement|ements)\b/i,
    /\bconfirm(?:s|ed|ation)?\b/i,
    /\breveal(?:s|ed)?\b/i
  ],

  termosAltaPrioridade: [
    /\btrailer\b/i,
    /\bgameplay\b/i,
    /\brelease date\b/i,
    /\bdelay(?:ed)?\b/i,
    /\blaunch\b/i,
    /\bnew footage\b/i,
    /\bleak(?:ed|s)?\b/i,
    /\bannouncement\b/i
  ]
};


// ==========================================================
// 1. FUNÇÕES AUXILIARES
// ==========================================================

function textoSeguro(valor) {
  if (typeof valor !== "string") {
    return "";
  }

  return valor.trim();
}


function normalizarTexto(valor) {
  return textoSeguro(valor)
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}


function detectarPadroes(texto, padroes) {
  return padroes.some(regex => regex.test(texto));
}


// ==========================================================
// 2. NORMALIZAÇÃO DE URL
// ==========================================================

function normalizarURL(valor) {
  if (typeof valor !== "string") {
    return null;
  }

  let url = valor.trim();

  if (!url) {
    return null;
  }

  // Aceita somente HTTP e HTTPS.
  if (!/^https?:\/\/[^\s/?#]+(?:[/?#]|$)/i.test(url)) {
    return null;
  }

  // Remove fragmentos.
  url = url.split("#")[0];

  // Separa endereço e parâmetros.
  const partes = url.split("?");

  const endereco = partes[0];

  if (partes.length === 1) {
    return endereco;
  }

  const parametros = partes
    .slice(1)
    .join("?")
    .split("&")
    .filter(parametro => {
      const chave = parametro.split("=")[0].toLowerCase();

      return !(
        chave.startsWith("utm_") ||
        chave === "fbclid" ||
        chave === "gclid"
      );
    });

  return parametros.length > 0
    ? endereco + "?" + parametros.join("&")
    : endereco;
}


// ==========================================================
// 3. ANÁLISE TEMPORAL
// ==========================================================

function calcularIdadeHoras(data) {
  const timestamp = Date.parse(data);

  if (!Number.isFinite(timestamp)) {
    return null;
  }

  const diferenca = (
    Date.now() - timestamp
  ) / 3600000;

  return Math.round(diferenca * 10) / 10;
}


// ==========================================================
// 4. CLASSIFICAÇÃO EDITORIAL
// ==========================================================

function classificarNoticia(titulo) {
  const tituloNormalizado = normalizarTexto(titulo);

  const vazamento = detectarPadroes(
    tituloNormalizado,
    CONFIG.termosVazamento
  );

  const possivelOficial = detectarPadroes(
    tituloNormalizado,
    CONFIG.termosOficiais
  );

  // Vazamentos têm precedência sobre anúncios.
  if (vazamento) {
    return {
      categoria: "POSSIVEL_RUMOR_OU_VAZAMENTO",
      tipo: "LEAK_OR_RUMOR",
      exige_fonte_primaria: true,
      risco_editorial: "ALTO"
    };
  }

  if (possivelOficial) {
    return {
      categoria: "POSSIVEL_ANUNCIO_OFICIAL",
      tipo: "POTENTIAL_OFFICIAL_NEWS",
      exige_fonte_primaria: true,
      risco_editorial: "MEDIO"
    };
  }

  return {
    categoria: "AGUARDANDO_CONFIRMACAO",
    tipo: "GENERAL_NEWS",
    exige_fonte_primaria: true,
    risco_editorial: "INDETERMINADO"
  };
}


// ==========================================================
// 5. PRIORIDADE EDITORIAL
// ==========================================================

function calcularPrioridade(titulo, idadeHoras) {
  let pontos = 0;

  const tituloNormalizado = normalizarTexto(titulo);

  if (
    detectarPadroes(
      tituloNormalizado,
      CONFIG.termosAltaPrioridade
    )
  ) {
    pontos += 40;
  }

  if (idadeHoras !== null && idadeHoras >= 0) {
    if (idadeHoras <= 24) {
      pontos += 40;
    } else if (idadeHoras <= 72) {
      pontos += 25;
    } else if (idadeHoras <= 168) {
      pontos += 10;
    }
  }

  if (
    detectarPadroes(
      tituloNormalizado,
      CONFIG.termosVazamento
    )
  ) {
    pontos += 10;
  }

  pontos = Math.min(pontos, 100);

  return {
    pontuacao: pontos,

    nivel:
      pontos >= 70
        ? "ALTA"
        : pontos >= 35
          ? "MEDIA"
          : "BAIXA"
  };
}


// ==========================================================
// 6. PROCESSAMENTO PRINCIPAL
// ==========================================================

const entrada = $input.all();

const urlsProcessadas = new Set();
const titulosProcessados = new Set();

const resultado = [];

for (const item of entrada) {
  const noticia = item.json || {};

  const titulo = textoSeguro(
    noticia.titulo || noticia.title
  );

  const conteudo = textoSeguro(
    noticia.conteudo ||
    noticia.contentSnippet ||
    noticia.content
  );

  const fonte = textoSeguro(
    noticia.fonte || "DESCONHECIDA"
  );

  const autor = textoSeguro(
    noticia.autor || noticia.creator
  );

  const data = textoSeguro(
    noticia.data ||
    noticia.isoDate ||
    noticia.pubDate
  );

  const linkOriginal = textoSeguro(
    noticia.link
  );

  const url = normalizarURL(linkOriginal);

  const tituloNormalizado = normalizarTexto(titulo);

  const erros = [];
  const alertas = [];


  // ========================================================
  // 7. VALIDAÇÃO DOS DADOS
  // ========================================================

  if (!titulo) {
    erros.push("TITULO_AUSENTE");
  }

  if (!url) {
    erros.push("URL_INVALIDA");
  }

  if (!fonte || fonte === "DESCONHECIDA") {
    alertas.push("FONTE_NAO_IDENTIFICADA");
  }

  if (!conteudo) {
    alertas.push("CONTEUDO_AUSENTE");
  } else if (conteudo.length < 150) {
    alertas.push("CONTEUDO_INSUFICIENTE");
  }


  // ========================================================
  // 8. RELEVÂNCIA GTA VI
  // ========================================================

  const relevanteGTA = detectarPadroes(
    titulo,
    CONFIG.palavrasGTA
  );

  if (!relevanteGTA) {
    erros.push("NOTICIA_FORA_DO_ESCOPO_GTA_VI");
  }


  // ========================================================
  // 9. DETECÇÃO DE DUPLICATAS
  // ========================================================

  let duplicada = false;

  if (url && urlsProcessadas.has(url)) {
    duplicada = true;
  }

  if (
    tituloNormalizado &&
    titulosProcessados.has(tituloNormalizado)
  ) {
    duplicada = true;
  }

  if (url) {
    urlsProcessadas.add(url);
  }

  if (tituloNormalizado) {
    titulosProcessados.add(tituloNormalizado);
  }

  if (duplicada) {
    erros.push("NOTICIA_DUPLICADA");
  }


  // ========================================================
  // 10. VALIDAÇÃO DA DATA
  // ========================================================

  const idadeHoras = calcularIdadeHoras(data);

  if (idadeHoras === null) {
    alertas.push("DATA_INVALIDA_OU_AUSENTE");
  } else if (idadeHoras < -1) {
    alertas.push("DATA_FUTURA");
  } else if (idadeHoras > CONFIG.maxIdadeHoras) {
    alertas.push("NOTICIA_ANTIGA");
  }


  // ========================================================
  // 11. CLASSIFICAÇÃO
  // ========================================================

  const classificacao = classificarNoticia(titulo);


  // ========================================================
  // 12. PRIORIDADE
  // ========================================================

  const prioridade = calcularPrioridade(
    titulo,
    idadeHoras
  );


  // ========================================================
  // 13. CONTROLE DE QUALIDADE
  // ========================================================

  const dadosValidos = erros.length === 0;

  const statusVerificacao = dadosValidos
    ? "AGUARDANDO_VERIFICACAO_INDEPENDENTE"
    : "REJEITADA_NA_TRIAGEM";


  // ========================================================
  // 14. RESULTADO ESTRUTURADO
  // ========================================================

  resultado.push({
    json: {
      projeto: CONFIG.projeto,

      versao_classificador: CONFIG.versao,

      idioma: CONFIG.idioma,

      noticia: {
        titulo,
        link: url,
        link_original: linkOriginal,
        data,
        autor,
        fonte,
        conteudo
      },

      analise: {
        relevante_gta_vi: relevanteGTA,

        classificacao_preliminar:
          classificacao.categoria,

        tipo_conteudo:
          classificacao.tipo,

        risco_editorial:
          classificacao.risco_editorial,

        exige_fonte_primaria:
          classificacao.exige_fonte_primaria,

        prioridade:
          prioridade.nivel,

        pontuacao_prioridade:
          prioridade.pontuacao,

        idade_horas:
          idadeHoras,

        duplicada
      },

      qualidade: {
        dados_validos: dadosValidos,
        erros,
        alertas
      },

      verificacao: {
        status: statusVerificacao,

        fontes_independentes_verificadas: 0,

        confirmacao_oficial: false,

        fatos_verificados: [],

        fatos_nao_verificados: [],

        revisao_humana_realizada: false
      },

      seguranca: {
        aprovado_para_producao: false,

        aprovado_para_publicacao: false,

        motivo_bloqueio:
          dadosValidos
            ? "VERIFICACAO_INDEPENDENTE_PENDENTE"
            : "ERRO_NA_TRIAGEM"
      },

      proxima_etapa: dadosValidos
        ? "PESQUISAR_FONTES_INDEPENDENTES"
        : "REVISAR_DADOS_DA_NOTICIA"
    }
  });
}


// ==========================================================
// 15. RETORNO PARA O N8N
// ==========================================================

return resultado;

/**
 * ============================================================
 * VICESCOPE | CROSS-SOURCE INTELLIGENCE V1.3
 * ============================================================
 *
 * Plataforma: n8n
 * Modo: Run Once for All Items
 *
 * Entrada:
 * RSS Read2 - Google Notícias
 *
 * Origem:
 * Code in JavaScript3 - Classificador V4.1
 *
 * OBJETIVOS:
 * - Recuperar notícias classificadas
 * - Identificar assuntos
 * - Comparar manchetes
 * - Identificar detalhes de acontecimentos
 * - Encontrar possíveis fontes relacionadas
 * - Preparar candidatos para análise com Gemini
 * - Impedir confirmação e publicação prematuras
 *
 * ATENÇÃO:
 * Correspondências não são comprovação dos fatos.
 * ============================================================
 */


// ============================================================
// 1. CONFIGURAÇÕES
// ============================================================

const CONFIG = {

  projeto: "ViceScope",

  versao: "1.3",

  nomesClassificador: [
    "Code in JavaScript3",
    "ViceScope_Classificador",
    "Código em JavaScript3"
  ],

  maxFontesPorNoticia: 12,

  maxCandidatosGemini: 5,

  similaridadeMinima: 0.25,

  fontesOficiais: [
    "rockstar games",
    "take-two interactive",
    "take two interactive"
  ],

  fontesJornalisticas: [
    "ign",
    "gamespot",
    "eurogamer",
    "vgc",
    "video games chronicle",
    "game informer",
    "gamesradar",
    "pc gamer",
    "polygon",
    "the verge",
    "kotaku",
    "rock paper shotgun",
    "rockstarintel",
    "mashable",
    "billboard",
    "gamingbible"
  ],

  palavrasIgnoradas: [
    "gta",
    "grand",
    "theft",
    "auto",
    "rockstar",
    "games",
    "game",
    "the",
    "and",
    "with",
    "from",
    "about",
    "this",
    "that",
    "what",
    "will",
    "for",
    "its",
    "are",
    "has",
    "have",
    "into",
    "more",
    "new",
    "official",
    "reveals",
    "revealed",
    "announced"
  ]

};


// ============================================================
// 2. FUNÇÕES BÁSICAS
// ============================================================

function texto(valor) {

  if (typeof valor === "string") {
    return valor.trim();
  }

  return "";

}


function primeiroTexto(...valores) {

  for (const valor of valores) {

    const resultado = texto(valor);

    if (resultado) {
      return resultado;
    }

  }

  return "";

}


function normalizar(valor) {

  return texto(valor)
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

}


function palavrasRelevantes(valor) {

  const palavras = normalizar(valor).split(" ");

  return [...new Set(
    palavras.filter(palavra => {

      return (
        palavra.length >= 3 &&
        !CONFIG.palavrasIgnoradas.includes(palavra)
      );

    })
  )];

}


// ============================================================
// 3. SIMILARIDADE DE MANCHETES
// ============================================================

function calcularSimilaridade(tituloA, tituloB) {

  const palavrasA = palavrasRelevantes(tituloA);
  const palavrasB = palavrasRelevantes(tituloB);

  if (
    palavrasA.length === 0 ||
    palavrasB.length === 0
  ) {
    return 0;
  }

  const conjuntoA = new Set(palavrasA);
  const conjuntoB = new Set(palavrasB);

  let comuns = 0;

  for (const palavra of conjuntoA) {

    if (conjuntoB.has(palavra)) {
      comuns++;
    }

  }

  const uniao = new Set([
    ...palavrasA,
    ...palavrasB
  ]);

  return comuns / uniao.size;

}


// ============================================================
// 4. IDENTIFICAR ASSUNTOS
// ============================================================

function identificarAssuntos(titulo) {

  const conteudo = normalizar(titulo);

  const categorias = {

    GAMEPLAY_LEAK: [
      /\bleak\b/,
      /\bleaks\b/,
      /\bleaked\b/,
      /\bfootage\b/,
      /\bunreleased\b/
    ],

    RADIO_AND_MUSIC: [
      /\bradio\b/,
      /\bradios\b/,
      /\bpodcast\b/,
      /\bpodcasts\b/,
      /\bmusic\b/,
      /\bstations\b/,
      /\bdj\b/
    ],

    MERCHANDISE: [
      /\bmerch\b/,
      /\bmerchandise\b/,
      /\bt shirt\b/,
      /\bclothing\b/,
      /\bapparel\b/,
      /\bcollection\b/
    ],

    POLICE_SYSTEM: [
      /\bpolice\b/,
      /\bcops\b/,
      /\bwanted\b/,
      /\bheat system\b/,
      /\blaw enforcement\b/
    ]

  };

  const encontrados = [];

  for (
    const [categoria, padroes]
    of Object.entries(categorias)
  ) {

    if (
      padroes.some(padrao =>
        padrao.test(conteudo)
      )
    ) {

      encontrados.push(categoria);

    }

  }

  return encontrados.length > 0
    ? encontrados
    : ["GENERAL_NEWS"];

}


// ============================================================
// 5. COMPARAR ASSUNTOS
// ============================================================

function compararAssuntos(tituloA, tituloB) {

  const assuntosA = identificarAssuntos(tituloA);
  const assuntosB = identificarAssuntos(tituloB);

  const comuns = assuntosA.filter(
    assunto =>
      assunto !== "GENERAL_NEWS" &&
      assuntosB.includes(assunto)
  );

  return {

    assuntos_original: assuntosA,

    assuntos_fonte: assuntosB,

    categorias_em_comum: comuns,

    assunto_compativel: comuns.length > 0

  };

}


// ============================================================
// 6. EXTRAIR DETALHES DO ACONTECIMENTO
// ============================================================

function extrairDetalhes(titulo) {

  const conteudo = normalizar(titulo);

  const detalhes = {

    duracao_minutos: null,

    quantidade_estacoes: null,

    menciona_podcast: false,

    menciona_vazamento: false,

    menciona_policia: false,

    menciona_produtos: false

  };


  // Duração de vídeos

  const duracao = conteudo.match(
    /\b(\d{1,3})\s*(?:minute|minutes|min)\b/
  );

  if (duracao) {

    detalhes.duracao_minutos =
      Number(duracao[1]);

  }


  // Quantidade de estações de rádio

  const estacoes = conteudo.match(
    /\b(\d{1,2})\s*(?:radio\s*)?stations\b/
  );

  if (estacoes) {

    detalhes.quantidade_estacoes =
      Number(estacoes[1]);

  }


  detalhes.menciona_podcast =
    /\bpodcasts?\b/.test(conteudo);

  detalhes.menciona_vazamento =
    /\bleaks?\b|\bleaked\b/.test(conteudo);

  detalhes.menciona_policia =
    /\bpolice\b|\bcops\b|\bwanted\b/.test(conteudo);

  detalhes.menciona_produtos =
    /\bmerch\b|\bmerchandise\b|\bt shirt\b/.test(conteudo);


  return detalhes;

}


// ============================================================
// 7. COMPARAR DETALHES
// ============================================================

function compararDetalhes(tituloA, tituloB) {

  const detalhesA = extrairDetalhes(tituloA);
  const detalhesB = extrairDetalhes(tituloB);

  const conflitos = [];
  const coincidencias = [];


  if (
    detalhesA.duracao_minutos !== null &&
    detalhesB.duracao_minutos !== null
  ) {

    if (
      detalhesA.duracao_minutos ===
      detalhesB.duracao_minutos
    ) {

      coincidencias.push(
        "MESMA_DURACAO_VIDEO"
      );

    } else {

      conflitos.push(
        "DURACAO_VIDEO_DIFERENTE"
      );

    }

  }


  if (
    detalhesA.quantidade_estacoes !== null &&
    detalhesB.quantidade_estacoes !== null
  ) {

    if (
      detalhesA.quantidade_estacoes ===
      detalhesB.quantidade_estacoes
    ) {

      coincidencias.push(
        "MESMA_QUANTIDADE_ESTACOES"
      );

    } else {

      conflitos.push(
        "QUANTIDADE_ESTACOES_DIFERENTE"
      );

    }

  }


  return {

    detalhes_original: detalhesA,

    detalhes_fonte: detalhesB,

    coincidencias,

    conflitos,

    possui_conflito: conflitos.length > 0

  };

}


// ============================================================
// 8. IDENTIFICAR FONTE
// ============================================================

function identificarFonte(dados) {

  if (
    typeof dados.source === "string"
  ) {

    return dados.source.trim();

  }


  if (
    dados.source &&
    typeof dados.source === "object"
  ) {

    const fonteObjeto = primeiroTexto(
      dados.source.title,
      dados.source.name
    );

    if (fonteObjeto) {
      return fonteObjeto;
    }

  }


  const titulo = primeiroTexto(
    dados.title,
    dados.titulo,
    dados["título"]
  );

  const posicao = titulo.lastIndexOf(" - ");

  if (posicao !== -1) {

    return titulo
      .slice(posicao + 3)
      .trim();

  }

  return "FONTE_NAO_IDENTIFICADA";

}


// ============================================================
// 9. LIMPAR TÍTULO
// ============================================================

function limparTitulo(titulo, fonte) {

  const valor = texto(titulo);

  const sufixo = " - " + fonte;

  if (
    fonte !== "FONTE_NAO_IDENTIFICADA" &&
    valor.toLowerCase().endsWith(
      sufixo.toLowerCase()
    )
  ) {

    return valor.slice(
      0,
      valor.length - sufixo.length
    );

  }

  return valor;

}


// ============================================================
// 10. CLASSIFICAR FONTE
// ============================================================

function classificarFonte(fonte) {

  const nome = normalizar(fonte);

  if (
    CONFIG.fontesOficiais.some(
      item => normalizar(item) === nome
    )
  ) {

    return "FONTE_PRIMARIA_POTENCIAL";

  }


  if (
    CONFIG.fontesJornalisticas.some(
      item => normalizar(item) === nome
    )
  ) {

    return "VEICULO_JORNALISTICO";

  }


  return "FONTE_NAO_CLASSIFICADA";

}


// ============================================================
// 11. RECUPERAR CLASSIFICADOR
// ============================================================

let noticiasOriginais = [];

let nomeClassificador = null;

const errosRecuperacao = [];


for (
  const nome
  of CONFIG.nomesClassificador
) {

  try {

    const dados = $(nome).all();

    if (!Array.isArray(dados)) {
      continue;
    }

    const validos = dados.filter(item => {

      const json = item.json || {};

      return (
        json.noticia &&
        typeof json.noticia === "object" &&
        primeiroTexto(
          json.noticia.titulo,
          json.noticia.Titulo,
          json.noticia["título"]
        )
      );

    });


    if (validos.length > 0) {

      noticiasOriginais = validos;

      nomeClassificador = nome;

      break;

    }

  } catch (erro) {

    errosRecuperacao.push(
      nome + ": " + erro.message
    );

  }

}


if (noticiasOriginais.length === 0) {

  throw new Error(
    "CLASSIFICADOR NAO ENCONTRADO. " +
    "Execute o fluxo completo e confira " +
    "o nome do no classificador. " +
    errosRecuperacao.join(" | ")
  );

}


// ============================================================
// 12. RECEBER GOOGLE NOTÍCIAS
// ============================================================

const entradaGoogle = $input.all();

const noticiasGoogle = [];


for (const item of entradaGoogle) {

  const dados = item.json || {};

  const fonte = identificarFonte(dados);

  const titulo = limparTitulo(
    primeiroTexto(
      dados.title,
      dados.titulo,
      dados["título"]
    ),
    fonte
  );


  if (!titulo) {
    continue;
  }


  noticiasGoogle.push({

    titulo,

    fonte,

    link: primeiroTexto(
      dados.link,
      dados.Link
    ),

    data: primeiroTexto(
      dados.isoDate,
      dados.pubDate,
      dados.data
    ),

    categoria_origem:
      classificarFonte(fonte),

    assuntos:
      identificarAssuntos(titulo)

  });

}


// ============================================================
// 13. CRUZAMENTO DE NOTÍCIAS
// ============================================================

const resultados = [];


for (const item of noticiasOriginais) {

  const noticia = item.json || {};

  const dadosNoticia = noticia.noticia || {};

  const tituloOriginal = primeiroTexto(
    dadosNoticia.titulo,
    dadosNoticia.Titulo,
    dadosNoticia["título"]
  );

  const fonteOriginal = primeiroTexto(
    dadosNoticia.fonte,
    noticia.fonte
  );

  const assuntosOriginais =
    identificarAssuntos(tituloOriginal);

  const correspondencias = [];


  for (const fonteGoogle of noticiasGoogle) {

    const comparacaoAssunto =
      compararAssuntos(
        tituloOriginal,
        fonteGoogle.titulo
      );

    const comparacaoDetalhes =
      compararDetalhes(
        tituloOriginal,
        fonteGoogle.titulo
      );

    const pontuacao =
      calcularSimilaridade(
        tituloOriginal,
        fonteGoogle.titulo
      );


    // Não comparar a notícia com o mesmo veículo

    if (
      normalizar(fonteGoogle.fonte) ===
      normalizar(fonteOriginal)
    ) {
      continue;
    }


    // Não aceitar conflitos conhecidos

    if (comparacaoDetalhes.possui_conflito) {
      continue;
    }


    // Exigir assunto em comum OU similaridade relevante

    if (
      !comparacaoAssunto.assunto_compativel &&
      pontuacao < CONFIG.similaridadeMinima
    ) {
      continue;
    }


    // Pontuação de triagem, não de veracidade

    let pontuacaoTriagem =
      pontuacao * 100;


    if (
      comparacaoAssunto.assunto_compativel
    ) {

      pontuacaoTriagem += 15;

    }


    pontuacaoTriagem +=
      comparacaoDetalhes.coincidencias.length * 15;


    pontuacaoTriagem = Math.min(
      100,
      Math.round(pontuacaoTriagem)
    );


    correspondencias.push({

      ...fonteGoogle,

      similaridade_titulo:
        Math.round(pontuacao * 100),

      pontuacao_triagem:
        pontuacaoTriagem,

      comparacao_assuntos:
        comparacaoAssunto,

      comparacao_detalhes:
        comparacaoDetalhes,

      status_evidencia:
        "CANDIDATO_NAO_VERIFICADO"

    });

  }


  // ==========================================================
  // 14. ORDENAR CORRESPONDÊNCIAS
  // ==========================================================

  correspondencias.sort(
    (a, b) =>
      b.pontuacao_triagem -
      a.pontuacao_triagem
  );


  // ==========================================================
  // 15. REMOVER VEÍCULOS DUPLICADOS
  // ==========================================================

  const fontesUnicas = [];

  const fontesRegistradas = new Set();


  for (const fonte of correspondencias) {

    const identificador =
      normalizar(fonte.fonte);

    if (
      fontesRegistradas.has(identificador)
    ) {
      continue;
    }

    fontesRegistradas.add(identificador);

    fontesUnicas.push(fonte);

    if (
      fontesUnicas.length >=
      CONFIG.maxFontesPorNoticia
    ) {
      break;
    }

  }


  // ==========================================================
  // 16. PREPARAR CANDIDATOS PARA GEMINI
  // ==========================================================

  const candidatosGemini =
    fontesUnicas
      .slice(
        0,
        CONFIG.maxCandidatosGemini
      )
      .map(fonte => ({

        titulo: fonte.titulo,

        fonte: fonte.fonte,

        link: fonte.link,

        data: fonte.data,

        assuntos:
          fonte.assuntos,

        pontuacao_triagem:
          fonte.pontuacao_triagem,

        comparacao_detalhes:
          fonte.comparacao_detalhes

      }));


  // ==========================================================
  // 17. CONTAR FONTES
  // ==========================================================

  const fontesPrimarias =
    fontesUnicas.filter(
      fonte =>
        fonte.categoria_origem ===
        "FONTE_PRIMARIA_POTENCIAL"
    );


  const fontesJornalisticas =
    fontesUnicas.filter(
      fonte =>
        fonte.categoria_origem ===
        "VEICULO_JORNALISTICO"
    );


  // ==========================================================
  // 18. RESULTADO FINAL
  // ==========================================================

  resultados.push({

    json: {

      ...noticia,

      inteligencia_assuntos: {

        versao: CONFIG.versao,

        assuntos_identificados:
          assuntosOriginais,

        titulo_analisado:
          tituloOriginal

      },

      cruzamento_fontes: {

        versao: CONFIG.versao,

        classificador_recuperado_de:
          nomeClassificador,

        total_resultados_pesquisados:
          noticiasGoogle.length,

        total_candidatos_brutos:
          correspondencias.length,

        total_fontes_relacionadas:
          fontesUnicas.length,

        fontes_primarias_potenciais:
          fontesPrimarias.length,

        veiculos_jornalisticos:
          fontesJornalisticas.length,

        fontes_encontradas:
          fontesUnicas,

        status:
          fontesUnicas.length > 0
            ? "CANDIDATOS_ENCONTRADOS"
            : "SEM_CANDIDATOS",

        verificacao_independente_concluida:
          false,

        observacao:
          "Correspondencias por assunto, detalhes " +
          "e similaridade. Ainda nao verificadas."

      },

      preparacao_gemini: {

        status:
          candidatosGemini.length > 0
            ? "PRONTO_PARA_ANALISE"
            : "SEM_CANDIDATOS",

        objetivo:
          "IDENTIFICAR_MESMO_ACONTECIMENTO",

        titulo_original:
          tituloOriginal,

        candidatos:
          candidatosGemini,

        total_candidatos:
          candidatosGemini.length,

        analise_executada: false

      },

      verificacao: {

        ...(noticia.verificacao || {}),

        status:
          "AGUARDANDO_ANALISE_DAS_EVIDENCIAS",

        fontes_independentes_verificadas: 0,

        confirmacao_oficial: false

      },

      seguranca: {

        ...(noticia.seguranca || {}),

        aprovado_para_producao: false,

        aprovado_para_publicacao: false,

        motivo_bloqueio:
          "EVIDENCIAS_AINDA_NAO_VERIFICADAS"

      },

      proxima_etapa:
        "COMPARAR_ACONTECIMENTOS_COM_GEMINI"

    }

  });

}


// ============================================================
// 19. RETORNO PARA N8N
// ============================================================

return resultados;

/**
 * ============================================================
 * VICESCOPE | VALIDADOR EDITORIAL V1.1
 * ============================================================
 *
 * Plataforma: n8n
 * Modo: Run Once for All Items
 *
 * ENTRADA:
 * ViceScope Gemini Verificador
 *
 * ORIGEM DOS DADOS:
 * Code in JavaScript4
 *
 * FUNÇÕES:
 * - Interpretar a resposta do Gemini
 * - Recuperar as notícias originais
 * - Validar títulos e candidatos
 * - Identificar correspondências
 * - Detectar inconsistências
 * - Identificar riscos editoriais
 * - Bloquear produção sem verificação
 *
 * IMPORTANTE:
 * Correspondência entre notícias NÃO comprova fatos.
 *
 * POLÍTICA DE SEGURANÇA:
 * FAIL CLOSED
 * ============================================================
 */


// ============================================================
// 1. CONFIGURAÇÕES
// ============================================================

const CONFIG = {

  projeto: "ViceScope",

  versao: "1.1",

  nomeOrigem: "Code in JavaScript4",

  limiarCorrespondencia: 80,

  classificacoesPermitidas: [
    "SAME_EVENT",
    "RELATED_BUT_DIFFERENT",
    "UNRELATED",
    "UNCERTAIN"
  ]

};


// ============================================================
// 2. FUNÇÕES AUXILIARES
// ============================================================

function texto(valor) {

  if (valor === null || valor === undefined) {
    return "";
  }

  return String(valor).trim();

}


function objeto(valor) {

  return (
    valor !== null &&
    typeof valor === "object" &&
    !Array.isArray(valor)
  )
    ? valor
    : {};

}


function lista(valor) {

  return Array.isArray(valor)
    ? valor
    : [];

}


function numero(valor, padrao = 0) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return padrao;
  }

  const resultado = Number(valor);

  return Number.isFinite(resultado)
    ? resultado
    : padrao;

}


function normalizar(valor) {

  return texto(valor)
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

}


function limitar(valor, minimo, maximo) {

  return Math.min(
    maximo,
    Math.max(minimo, valor)
  );

}


// ============================================================
// 3. EXTRAIR RESPOSTA DO GEMINI
// ============================================================

function extrairGemini(item) {

  const dados = objeto(item.json);

  if (
    dados.versao &&
    Array.isArray(dados.resultados)
  ) {
    return dados;
  }

  const campos = [
    dados.text,
    dados.output,
    dados.response,
    dados.content
  ];

  for (const campo of campos) {

    if (typeof campo === "string" && campo.trim()) {
      return campo;
    }

  }

  const candidatos = lista(dados.candidates);

  for (const candidato of candidatos) {

    const partes = lista(
      candidato?.content?.parts
    );

    const conteudo = partes
      .map(parte => parte?.text)
      .filter(parte => typeof parte === "string")
      .join("\n");

    if (conteudo) {
      return conteudo;
    }

  }

  const partesDiretas = lista(
    dados.content?.parts
  );

  if (partesDiretas.length > 0) {

    return partesDiretas
      .map(parte => parte?.text)
      .filter(parte => typeof parte === "string")
      .join("\n");

  }

  throw new Error(
    "RESPOSTA_GEMINI_NAO_ENCONTRADA"
  );

}


// ============================================================
// 4. INTERPRETAR JSON
// ============================================================

function interpretarJSON(resposta) {

  if (
    resposta &&
    typeof resposta === "object"
  ) {
    return resposta;
  }

  let conteudo = texto(resposta);

  if (!conteudo) {

    throw new Error(
      "RESPOSTA_GEMINI_VAZIA"
    );

  }

  conteudo = conteudo
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {

    return JSON.parse(conteudo);

  } catch (erro) {

    const inicio = conteudo.indexOf("{");
    const fim = conteudo.lastIndexOf("}");

    if (inicio >= 0 && fim > inicio) {

      return JSON.parse(
        conteudo.slice(inicio, fim + 1)
      );

    }

    throw new Error(
      "JSON_GEMINI_INVALIDO"
    );

  }

}


// ============================================================
// 5. RECUPERAR NOTÍCIAS ORIGINAIS
// ============================================================

let noticiasOriginais = [];

let erroOrigem = null;

try {

  noticiasOriginais = $(
    CONFIG.nomeOrigem
  ).all();

} catch (erro) {

  erroOrigem = erro.message;

}


// ============================================================
// 6. RECEBER RESPOSTAS DO GEMINI
// ============================================================

const respostasGemini = $input.all();

const resultadosFinais = [];


// ============================================================
// 7. PROCESSAR NOTÍCIAS
// ============================================================

for (
  let indiceNoticia = 0;
  indiceNoticia < respostasGemini.length;
  indiceNoticia++
) {

  const itemGemini =
    respostasGemini[indiceNoticia];

  const origem = objeto(
    noticiasOriginais[indiceNoticia]?.json
  );

  const erros = [];
  const alertas = [];

  let analiseGemini = {};

  let jsonGeminiValido = false;


  // ==========================================================
  // 8. INTERPRETAR RESPOSTA
  // ==========================================================

  try {

    const resposta = extrairGemini(
      itemGemini
    );

    analiseGemini = objeto(
      interpretarJSON(resposta)
    );

    jsonGeminiValido = true;

  } catch (erro) {

    erros.push(
      "ERRO_JSON_GEMINI: " + erro.message
    );

  }


  // ==========================================================
  // 9. VALIDAR NOTÍCIA ORIGINAL
  // ==========================================================

  if (erroOrigem) {

    erros.push(
      "ERRO_ORIGEM: " + erroOrigem
    );

  }

  if (!origem.noticia) {

    erros.push(
      "NOTICIA_ORIGINAL_NAO_ENCONTRADA"
    );

  }

  const noticia = objeto(
    origem.noticia
  );

  const tituloOriginal = texto(
    noticia.titulo ||
    noticia.Titulo ||
    noticia["título"]
  );

  const tituloGemini = texto(
    analiseGemini.titulo_original
  );

  if (!tituloOriginal) {

    erros.push(
      "TITULO_ORIGINAL_AUSENTE"
    );

  }

  if (!tituloGemini) {

    erros.push(
      "TITULO_GEMINI_AUSENTE"
    );

  }

  if (
    tituloOriginal &&
    tituloGemini &&
    normalizar(tituloOriginal) !==
    normalizar(tituloGemini)
  ) {

    erros.push(
      "TITULO_ORIGINAL_DIVERGENTE"
    );

  }


  // ==========================================================
  // 10. RECUPERAR CANDIDATOS
  // ==========================================================

  const preparacao = objeto(
    origem.preparacao_gemini
  );

  const candidatosOriginais = lista(
    preparacao.candidatos
  );

  const resultadosGemini = lista(
    analiseGemini.resultados
  );

  if (!Array.isArray(analiseGemini.resultados)) {

    erros.push(
      "RESULTADOS_GEMINI_INVALIDOS"
    );

  }

  if (
    candidatosOriginais.length !==
    resultadosGemini.length
  ) {

    erros.push(
      "QUANTIDADE_CANDIDATOS_DIVERGENTE"
    );

  }

  if (
    numero(
      analiseGemini.candidatos_analisados,
      -1
    ) !== candidatosOriginais.length
  ) {

    erros.push(
      "CONTAGEM_CANDIDATOS_INCONSISTENTE"
    );

  }


  // ==========================================================
  // 11. VALIDAR CORRESPONDÊNCIAS
  // ==========================================================

  const correspondencias = [];

  const indicesProcessados = new Set();

  for (
    let i = 0;
    i < resultadosGemini.length;
    i++
  ) {

    const resultado = objeto(
      resultadosGemini[i]
    );

    const indice = numero(
      resultado.indice,
      -1
    );

    if (
      !Number.isInteger(indice) ||
      indice < 0 ||
      indice >= candidatosOriginais.length
    ) {

      erros.push(
        `INDICE_INVALIDO_${i}`
      );

      continue;

    }

    if (indicesProcessados.has(indice)) {

      erros.push(
        `INDICE_DUPLICADO_${indice}`
      );

      continue;

    }

    indicesProcessados.add(indice);

    const candidato = objeto(
      candidatosOriginais[indice]
    );

    const tituloCandidato = texto(
      candidato.titulo ||
      candidato.title
    );

    const fonteCandidato = texto(
      candidato.fonte ||
      candidato.source
    );

    const tituloResposta = texto(
      resultado.titulo
    );

    const fonteResposta = texto(
      resultado.fonte
    );

    if (
      normalizar(tituloCandidato) !==
      normalizar(tituloResposta)
    ) {

      erros.push(
        `TITULO_CANDIDATO_DIVERGENTE_${indice}`
      );

    }

    if (
      normalizar(fonteCandidato) !==
      normalizar(fonteResposta)
    ) {

      erros.push(
        `FONTE_CANDIDATO_DIVERGENTE_${indice}`
      );

    }

    const classificacao = texto(
      resultado.classificacao
    ).toUpperCase();

    if (
      !CONFIG.classificacoesPermitidas.includes(
        classificacao
      )
    ) {

      erros.push(
        `CLASSIFICACAO_INVALIDA_${indice}`
      );

    }

    const confianca = limitar(
      numero(
        resultado.confianca_correspondencia
      ),
      0,
      100
    );

    const correspondenciaForte = (
      classificacao === "SAME_EVENT" &&
      confianca >= CONFIG.limiarCorrespondencia
    );

    correspondencias.push({

      indice,

      titulo: tituloCandidato,

      fonte: fonteCandidato,

      link: texto(
        candidato.link ||
        candidato.url
      ),

      classificacao,

      confianca_correspondencia:
        confianca,

      correspondencia_forte:
        correspondenciaForte,

      justificativa: texto(
        resultado.justificativa
      ),

      detalhes_coincidentes: lista(
        resultado.detalhes_coincidentes
      ),

      possiveis_contradicoes: lista(
        resultado.possiveis_contradicoes
      ),

      conteudo_original_verificado: false,

      fonte_independente_verificada: false,

      fonte_oficial_autenticada: false

    });

  }


  // ==========================================================
  // 12. CONTAGENS
  // ==========================================================

  const totalMesmoEvento =
    correspondencias.filter(
      item =>
        item.classificacao === "SAME_EVENT"
    ).length;

  const totalIncertos =
    correspondencias.filter(
      item =>
        item.classificacao === "UNCERTAIN"
    ).length;

  const totalFortes =
    correspondencias.filter(
      item =>
        item.correspondencia_forte
    ).length;


  if (
    numero(
      analiseGemini.total_mesmo_acontecimento,
      -1
    ) !== totalMesmoEvento
  ) {

    erros.push(
      "TOTAL_MESMO_EVENTO_INCONSISTENTE"
    );

  }

  if (
    numero(
      analiseGemini.total_incertos,
      -1
    ) !== totalIncertos
  ) {

    erros.push(
      "TOTAL_INCERTOS_INCONSISTENTE"
    );

  }


  // ==========================================================
  // 13. DETECTAR RISCO EDITORIAL
  // ==========================================================

  const analiseOriginal = objeto(
    origem.analise
  );

  const riscoOriginal = texto(
    analiseOriginal.risco_editorial
  );

  const textoRisco = normalizar(
    [
      tituloOriginal,
      riscoOriginal,
      analiseOriginal.tipo_conteudo,
      analiseOriginal.classificacao_preliminar
    ].join(" ")
  );

  const riscoVazamento =
    /\b(leak|leaks|leaked|rumor|rumors|vazamento|boato)\b/
      .test(textoRisco);

  const riscoAlto =
    /\b(high|alto|critical|critico)\b/
      .test(normalizar(riscoOriginal));

  const riscoElevado =
    riscoVazamento || riscoAlto;

  if (riscoElevado) {

    alertas.push(
      "RISCO_EDITORIAL_ELEVADO"
    );

  }

  if (candidatosOriginais.length === 0) {

    alertas.push(
      "SEM_CANDIDATOS"
    );

  }

  if (totalMesmoEvento === 0) {

    alertas.push(
      "SEM_CORRESPONDENCIAS_CONFIRMADAS"
    );

  }


  // ==========================================================
  // 14. IMPEDIR APROVAÇÃO INDEVIDA
  // ==========================================================

  if (
    analiseGemini.aprovado_para_producao === true ||
    analiseGemini.aprovado_para_publicacao === true ||
    analiseGemini.confirmacao_oficial === true ||
    numero(
      analiseGemini.fontes_independentes_verificadas
    ) > 0
  ) {

    erros.push(
      "APROVACAO_INDEVIDA_PELO_GEMINI"
    );

  }


  // ==========================================================
  // 15. DEFINIR STATUS
  // ==========================================================

  const validacaoOK = (
    jsonGeminiValido &&
    erros.length === 0
  );

  let status = "ERRO_VALIDACAO";

  if (validacaoOK) {

    if (candidatosOriginais.length === 0) {

      status = "SEM_CANDIDATOS";

    } else if (totalMesmoEvento === 0) {

      status = "SEM_CORRESPONDENCIAS";

    } else if (riscoElevado) {

      status = "REVISAO_EDITORIAL_PRIORITARIA";

    } else {

      status = "AGUARDANDO_VERIFICACAO_DAS_FONTES";

    }

  }


  // ==========================================================
  // 16. RESULTADO FINAL
  // ==========================================================

  resultadosFinais.push({

    json: {

      ...origem,

      projeto: CONFIG.projeto,

      validador_editorial: {

        versao: CONFIG.versao,

        status,

        validacao_estrutural_ok:
          validacaoOK,

        titulo_original:
          tituloOriginal,

        candidatos_recebidos:
          candidatosOriginais.length,

        candidatos_analisados:
          correspondencias.length,

        total_mesmo_acontecimento:
          totalMesmoEvento,

        total_correspondencias_fortes:
          totalFortes,

        total_incertos:
          totalIncertos,

        limiar_correspondencia:
          CONFIG.limiarCorrespondencia,

        risco_editorial_elevado:
          riscoElevado,

        correspondencias,

        alertas: [
          ...lista(
