return resultadosFinais;

/**
 * ============================================================
 * VICESCOPE | PREPARADOR DE FONTES V1.2
 * ============================================================
 *
 * n8n: Run Once for All Items
 *
 * CORREÇÕES:
 * - Não depende da classe global URL
 * - Aceita URLs HTTPS e HTTP
 * - Identifica links do Google News
 * - Evita URLs duplicadas
 * - Limita consultas por notícia
 * - Mostra diagnóstico quando não há fontes
 * - Mantém produção e publicação bloqueadas
 *
 * ============================================================
 */

const CONFIG = {
  projeto: "ViceScope",
  versao: "1.2",
  maxFontesRelacionadas: 3,
  confiancaMinima: 80,
  incluirFontePrincipal: true
};


// ============================================================
// FUNÇÕES AUXILIARES
// ============================================================

function texto(valor) {
  return String(valor ?? "").trim();
}

function lista(valor) {
  return Array.isArray(valor) ? valor : [];
}

function objeto(valor) {
  return valor &&
    typeof valor === "object" &&
    !Array.isArray(valor)
      ? valor
      : {};
}

function numero(valor, padrao = 0) {
  if (valor === null || valor === undefined || valor === "") {
    return padrao;
  }

  const n = Number(valor);
  return Number.isFinite(n) ? n : padrao;
}


// ============================================================
// ANALISAR URL SEM USAR new URL()
// ============================================================

function analisarURL(valor) {
  const endereco = texto(valor);

  if (!endereco) {
    return {
      valida: false,
      motivo: "URL_VAZIA"
    };
  }

  if (endereco.length > 2048) {
    return {
      valida: false,
      motivo: "URL_MUITO_LONGA"
    };
  }

  if (/[\s<>"'\\]/.test(endereco)) {
    return {
      valida: false,
      motivo: "CARACTERES_INVALIDOS"
    };
  }

  const resultado = endereco.match(
    /^(https?):\/\/([^/?#]+)(?:[/?#]|$)/i
  );

  if (!resultado) {
    return {
      valida: false,
      motivo: "FORMATO_URL_INVALIDO"
    };
  }

  const protocolo = resultado[1].toLowerCase();
  const autoridade = resultado[2].toLowerCase();

  if (autoridade.includes("@")) {
    return {
      valida: false,
      motivo: "CREDENCIAIS_NA_URL"
    };
  }

  if (autoridade.startsWith("[")) {
    return {
      valida: false,
      motivo: "IPV6_DIRETO_BLOQUEADO"
    };
  }

  const partes = autoridade.split(":");

  if (partes.length > 2) {
    return {
      valida: false,
      motivo: "HOST_INVALIDO"
    };
  }

  const dominio = partes[0];
  const porta = partes[1] || "";

  if (
    porta &&
    !["80", "443"].includes(porta)
  ) {
    return {
      valida: false,
      motivo: "PORTA_NAO_PERMITIDA"
    };
  }

  if (
    !dominio ||
    dominio === "localhost" ||
    dominio.endsWith(".localhost") ||
    dominio.endsWith(".local") ||
    dominio.endsWith(".internal")
  ) {
    return {
      valida: false,
      motivo: "HOST_LOCAL_BLOQUEADO"
    };
  }

  // Bloqueia endereços IP diretos.
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(dominio)) {
    return {
      valida: false,
      motivo: "IP_DIRETO_BLOQUEADO"
    };
  }

  if (
    !/^[a-z0-9.-]+$/.test(dominio) ||
    !dominio.includes(".") ||
    dominio.startsWith(".") ||
    dominio.endsWith(".") ||
    dominio.includes("..") ||
    dominio.split(".").some(
      parte => !parte || parte.startsWith("-") || parte.endsWith("-")
    )
  ) {
    return {
      valida: false,
      motivo: "DOMINIO_INVALIDO"
    };
  }

  return {
    valida: true,
    url: endereco,
    dominio,
    protocolo,
    google_news:
      dominio === "news.google.com"
  };
}


// ============================================================
// NORMALIZAR URL
// ============================================================

function normalizarURL(valor) {
  const analise = analisarURL(valor);

  if (!analise.valida) {
    return "";
  }

  return analise.url
    .split("#")[0]
    .replace(/\/$/, "");
}


// ============================================================
// IDENTIFICAR DOMÍNIO OFICIAL POTENCIAL
// ============================================================

function dominioOficial(dominio) {
  const dominios = [
    "rockstargames.com",
    "take2games.com"
  ];

  return dominios.some(
    oficial =>
      dominio === oficial ||
      dominio.endsWith("." + oficial)
  );
}


// ============================================================
// ENTRADA
// ============================================================

const entrada = $input.all();

const consultas = [];

const urlsRegistradas = new Map();

const diagnostico = {
  noticias_recebidas: entrada.length,
  noticias_validas: 0,
  noticias_bloqueadas: 0,
  fontes_principais: 0,
  fontes_relacionadas: 0,
  urls_duplicadas: 0,
  urls_invalidas: 0,
  urls_invalidas_detalhes: [],
  bloqueios: [],
  total_consultas: 0
};


// ============================================================
// REGISTRAR FONTE
// ============================================================

function registrarFonte(fonte, indiceNoticia, tituloNoticia) {
  const analise = analisarURL(fonte.url);

  if (!analise.valida) {
    diagnostico.urls_invalidas++;

    diagnostico.urls_invalidas_detalhes.push({
      indice_noticia: indiceNoticia,
      fonte: fonte.fonte,
      motivo: analise.motivo,
      url_inicio: texto(fonte.url).slice(0, 150)
    });

    return;
  }

  const urlNormalizada = normalizarURL(fonte.url);

  if (urlsRegistradas.has(urlNormalizada)) {
    const indiceExistente = urlsRegistradas.get(urlNormalizada);
    const existente = consultas[indiceExistente];

    if (!existente.noticias_relacionadas.includes(indiceNoticia)) {
      existente.noticias_relacionadas.push(indiceNoticia);
    }

    diagnostico.urls_duplicadas++;
    return;
  }

  const oficialPotencial = dominioOficial(analise.dominio);

  urlsRegistradas.set(urlNormalizada, consultas.length);

  consultas.push({
    projeto: CONFIG.projeto,
    versao: CONFIG.versao,

    tipo_registro: "CONSULTA_FONTE",

    indice_noticia: indiceNoticia,
    noticias_relacionadas: [indiceNoticia],

    titulo_noticia: tituloNoticia,
    titulo_fonte: fonte.titulo,
    nome_fonte: fonte.fonte,

    tipo_fonte: fonte.tipo,

    url_consulta: analise.url,
    dominio: analise.dominio,

    link_google_news: analise.google_news,

    dominio_oficial_potencial: oficialPotencial,

    prioridade: fonte.prioridade,

    status: "AGUARDANDO_HTTP",

    fonte_autenticada: false,
    conteudo_verificado: false,

    aprovado_para_producao: false,
    aprovado_para_publicacao: false
  });
}


// ============================================================
// PROCESSAR NOTÍCIAS
// ============================================================

for (let i = 0; i < entrada.length; i++) {
  const dados = objeto(entrada[i].json);
  const noticia = objeto(dados.noticia);
  const validador = objeto(dados.validador_editorial);

  const tituloNoticia = texto(
    noticia.titulo ||
    noticia.Titulo ||
    noticia["título"]
  );

  // Preserva o bloqueio estrutural.
  if (validador.validacao_estrutural_ok !== true) {
    diagnostico.noticias_bloqueadas++;

    diagnostico.bloqueios.push({
      indice_noticia: i,
      titulo: tituloNoticia,
      status: texto(validador.status),
      erros: lista(validador.erros),
      motivo: "VALIDACAO_ESTRUTURAL_INVALIDA"
    });

    continue;
  }

  diagnostico.noticias_validas++;

  // Fonte principal
  if (CONFIG.incluirFontePrincipal) {
    const linkPrincipal = texto(
      noticia.link_original ||
      noticia.Link ||
      noticia.link
    );

    if (linkPrincipal) {
      diagnostico.fontes_principais++;

      registrarFonte({
        titulo: tituloNoticia,
        fonte: texto(noticia.fonte),
        url: linkPrincipal,
        tipo: "FONTE_PRINCIPAL",
        prioridade: 100
      }, i, tituloNoticia);
    }
  }

  // Fontes relacionadas
  const correspondencias = lista(
    validador.correspondencias
  );

  const relacionadas = correspondencias
    .filter(fonte =>
      fonte.correspondencia_forte === true &&
      numero(fonte.confianca_correspondencia) >=
        CONFIG.confiancaMinima
    )
    .map(fonte => ({
      titulo: texto(fonte.titulo),
      fonte: texto(fonte.fonte),
      url: texto(fonte.link),
      tipo: "FONTE_RELACIONADA",
      prioridade: numero(fonte.confianca_correspondencia)
    }))
    .filter(fonte => analisarURL(fonte.url).valida)
    .sort((a, b) => b.prioridade - a.prioridade)
    .slice(0, CONFIG.maxFontesRelacionadas);

  diagnostico.fontes_relacionadas += relacionadas.length;

  for (const fonte of relacionadas) {
    registrarFonte(fonte, i, tituloNoticia);
  }
}


// ============================================================
// DIAGNÓSTICO FINAL
// ============================================================

diagnostico.total_consultas = consultas.length;

diagnostico.status = consultas.length > 0
  ? "CONSULTAS_PREPARADAS"
  : "NENHUMA_CONSULTA_PREPARADA";


// ============================================================
// RETORNAR RESULTADOS
// ============================================================

if (consultas.length === 0) {
  return [{
    json: {
      projeto: CONFIG.projeto,
      versao: CONFIG.versao,
      tipo_registro: "DIAGNOSTICO",
      status: "NENHUMA_FONTE_LIBERADA_PARA_CONSULTA",
      diagnostico,
      seguranca: {
        aprovado_para_producao: false,
        aprovado_para_publicacao: false,
        motivo_bloqueio: "FONTES_NAO_PREPARADAS"
      },
      proxima_etapa: "ANALISAR_DIAGNOSTICO"
    }
  }];
}

return consultas.map(consulta => ({
  json: {
    ...consulta,
    diagnostico_resumo: {
      noticias_recebidas: diagnostico.noticias_recebidas,
      noticias_validas: diagnostico.noticias_validas,
      noticias_bloqueadas: diagnostico.noticias_bloqueadas,
      urls_invalidas: diagnostico.urls_invalidas,
      urls_duplicadas: diagnostico.urls_duplicadas,
      total_consultas: diagnostico.total_consultas
    }
  }
}));

function responseText(value) {
  if (typeof value === 'string') {
    try { const parsed = JSON.parse(value); if (parsed?._readableState) value = parsed; else return value; }
    catch { return value; }
  }
  const chunks = value?._readableState?.buffer;
  if (Array.isArray(chunks)) {
    return chunks.map(chunk => chunk?.type === 'Buffer' && Array.isArray(chunk.data) ? Buffer.from(chunk.data).toString('utf8') : '').join('');
  }
  return typeof value === 'string' ? value : '';
}
// ============================================================
// VICESCOPE - ANALISADOR DE RESPOSTAS HTTP V1.0
// ============================================================
//
// OBJETIVO:
// Analisar as respostas HTTP das fontes jornalísticas.
//
// IDENTIFICA:
// - Bloqueios Cloudflare
// - Páginas intermediárias do Google Notícias
// - Erros HTTP
// - Conteúdo insuficiente
// - Possíveis artigos acessíveis
//
// SEGURANÇA EDITORIAL:
// HTTP 200 NÃO significa notícia confirmada.
//
// Nenhuma fonte será aprovada automaticamente para produção
// ou publicação.
//
// COMPATÍVEL COM:
// n8n Code Node - Run Once for All Items
//
// ============================================================


// ------------------------------------------------------------
// 1. CONFIGURAÇÕES
// ------------------------------------------------------------

const CONFIG = {
  projeto: "ViceScope",

  versao: "1.0",

  tamanho_minimo_html: 500,

  tamanho_maximo_texto: 2500,

  guardar_html_completo: false,

  permitir_aprovacao_automatica: false
};


// ------------------------------------------------------------
// 2. RECEBER RESPOSTAS HTTP
// ------------------------------------------------------------

const respostas = $input.all();


// ------------------------------------------------------------
// 3. RECUPERAR METADADOS ORIGINAIS
// ------------------------------------------------------------

let fontesOriginais = [];

try {

  fontesOriginais = $(
    "ViceScope URLs resolvidas"
  ).all();

} catch (erro) {

  fontesOriginais = [];

}


// ------------------------------------------------------------
// 4. FUNÇÕES AUXILIARES
// ------------------------------------------------------------

function textoSeguro(valor) {

  if (valor === null || valor === undefined) {
    return "";
  }

  return String(valor);

}


function normalizarTexto(valor) {

  return textoSeguro(valor)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();

}


function obterDominio(url) {

  const endereco = textoSeguro(url).trim();

  const resultado = endereco.match(
    /^https?:\/\/([^\/?#:]+)/i
  );

  if (!resultado) {
    return "";
  }

  return resultado[1].toLowerCase();

}


function limparHTML(html) {

  let texto = textoSeguro(html);

  texto = texto.replace(
    /<script\b[^>]*>[\s\S]*?<\/script>/gi,
    " "
  );

  texto = texto.replace(
    /<style\b[^>]*>[\s\S]*?<\/style>/gi,
    " "
  );

  texto = texto.replace(
    /<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi,
    " "
  );

  texto = texto.replace(
    /<[^>]+>/g,
    " "
  );

  texto = texto
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");

  texto = texto.replace(
    /\s+/g,
    " "
  ).trim();

  return texto.slice(
    0,
    CONFIG.tamanho_maximo_texto
  );

}


function extrairTituloHTML(html) {

  const resultado = textoSeguro(html).match(
    /<title[^>]*>([\s\S]*?)<\/title>/i
  );

  if (!resultado) {
    return "";
  }

  return resultado[1]
    .replace(/\s+/g, " ")
    .trim();

}


function identificarCloudflare(html, headers) {

  const conteudo = normalizarTexto(
    textoSeguro(html).slice(0, 12000)
  );

  const mitigacao = normalizarTexto(
    headers["cf-mitigated"] ||
    headers["CF-Mitigated"]
  );

  if (mitigacao === "challenge") {
    return true;
  }

  const indicadores = [
    "just a moment...",
    "challenges.cloudflare.com",
    "cf_chl_opt",
    "cdn-cgi/challenge-platform"
  ];

  return indicadores.some(
    indicador => conteudo.includes(indicador)
  );

}


function identificarGoogleNews(html, dominio) {

  const conteudo = normalizarTexto(
    textoSeguro(html).slice(0, 12000)
  );

  if (
    dominio === "news.google.com" ||
    dominio === "www.news.google.com"
  ) {

    return (
      conteudo.includes("<html") ||
      conteudo.includes("google news") ||
      conteudo.includes("dotsplashui")
    );

  }

  return false;

}


function classificarResposta(
  statusCode,
  html,
  headers,
  dominio,
  erro
) {

  if (
    identificarCloudflare(html, headers)
  ) {

    return {
      status: "BLOQUEADO_CLOUDFLARE",

      acessivel: false,

      motivo:
        "O servidor retornou uma proteção Cloudflare."
    };

  }


  if (erro) {

    return {
      status: "ERRO_HTTP",

      acessivel: false,

      motivo:
        "Falha de conexão ou execução da requisição."
    };

  }


  if (
    !Number.isFinite(statusCode) ||
    statusCode < 200 ||
    statusCode >= 300
  ) {

    return {
      status: "ERRO_HTTP",

      acessivel: false,

      motivo:
        "O servidor retornou HTTP " + statusCode
    };

  }


  if (
    identificarGoogleNews(html, dominio)
  ) {

    return {
      status: "PAGINA_INTERMEDIARIA_GOOGLE",

      acessivel: false,

      motivo:
        "O Google Notícias retornou sua própria página, não o artigo original."
    };

  }


  if (
    textoSeguro(html).length <
    CONFIG.tamanho_minimo_html
  ) {

    return {
      status: "CONTEUDO_INSUFICIENTE",

      acessivel: false,

      motivo:
        "A resposta contém pouco conteúdo para análise."
    };

  }


  const conteudoNormalizado = normalizarTexto(
    textoSeguro(html).slice(0, 20000)
  );

  const bloqueiosGenericos = [
    "access denied",
    "enable javascript and cookies",
    "please enable javascript",
    "verify you are human",
    "checking your browser",
    "captcha"
  ];


  if (
    bloqueiosGenericos.some(
      indicador =>
        conteudoNormalizado.includes(indicador)
    )
  ) {

    return {
      status: "CONTEUDO_INSUFICIENTE",

      acessivel: false,

      motivo:
        "A página apresenta indicadores de bloqueio ou verificação."
    };

  }


  const pareceHTML = /<html\b|<article\b|<body\b/i.test(
    textoSeguro(html).slice(0, 20000)
  );


  if (!pareceHTML) {

    return {
      status: "CONTEUDO_INSUFICIENTE",

      acessivel: false,

      motivo:
        "A resposta não apresenta estrutura HTML reconhecível."
    };

  }


  return {
    status: "ARTIGO_ACESSIVEL",

    acessivel: true,

    motivo:
      "Foi recebida uma página HTML candidata à extração. O artigo ainda precisa ser validado."
  };

}


// ------------------------------------------------------------
// 5. PROCESSAR RESPOSTAS
// ------------------------------------------------------------

const resultados = [];

const resumo = {

  total_consultas: respostas.length,

  bloqueado_cloudflare: 0,

  pagina_intermediaria_google: 0,

  artigo_acessivel: 0,

  erro_http: 0,

  conteudo_insuficiente: 0,

  fontes_verificadas: 0,

  aprovadas_para_producao: 0,

  aprovadas_para_publicacao: 0

};


for (
  let indice = 0;
  indice < respostas.length;
  indice++
) {

  const item = respostas[indice];

  const resposta = item.json || {};


  // ----------------------------------------------------------
  // 5.1. IDENTIFICAR ITEM ORIGINAL
  // ----------------------------------------------------------

  const pareamento = item.pairedItem;

  let indiceOriginal = indice;

  if (
    pareamento &&
    Number.isInteger(pareamento.item)
  ) {

    indiceOriginal = pareamento.item;

  }


  const originalEncontrado =
    fontesOriginais[indiceOriginal] || null;

  const metadados =
    originalEncontrado
      ? originalEncontrado.json || {}
      : {};


  // ----------------------------------------------------------
  // 5.2. RECUPERAR RESPOSTA HTTP
  // ----------------------------------------------------------

  const html = responseText(
    resposta.html ||
    resposta.body ||
    resposta.data ||
    ""
  );

  const headers = resposta.headers || {};

  const statusCodeBruto =
    resposta.statusCode ??
    resposta.status ??
    null;

  const statusCode =
    statusCodeBruto === null ||
    statusCodeBruto === ""
      ? NaN
      : Number(statusCodeBruto);


  const erro = Boolean(
    resposta.error ||
    resposta.message && !Number.isFinite(statusCode)
  );


  // ----------------------------------------------------------
  // 5.3. IDENTIFICAR FONTE
  // ----------------------------------------------------------

  const urlConsulta = textoSeguro(
    metadados.url_consulta ||
    resposta.url_consulta ||
    ""
  );

  const dominio =
    obterDominio(urlConsulta) ||
    textoSeguro(metadados.dominio);


  // ----------------------------------------------------------
  // 5.4. CLASSIFICAR
  // ----------------------------------------------------------

  const classificacao = classificarResposta(
    statusCode,
    html,
    headers,
    dominio,
    erro
  );


  // ----------------------------------------------------------
  // 5.5. ATUALIZAR ESTATÍSTICAS
  // ----------------------------------------------------------

  switch (classificacao.status) {

    case "BLOQUEADO_CLOUDFLARE":

      resumo.bloqueado_cloudflare++;
      break;


    case "PAGINA_INTERMEDIARIA_GOOGLE":

      resumo.pagina_intermediaria_google++;
      break;


    case "ARTIGO_ACESSIVEL":

      resumo.artigo_acessivel++;
      break;


    case "ERRO_HTTP":

      resumo.erro_http++;
      break;


    default:

      resumo.conteudo_insuficiente++;
      break;

  }


  // ----------------------------------------------------------
  // 5.6. EXTRAIR INFORMAÇÕES BÁSICAS
  // ----------------------------------------------------------

  const tituloHTML = extrairTituloHTML(html);

  const textoExtraido =
    classificacao.acessivel
      ? limparHTML(html)
      : "";


  // ----------------------------------------------------------
  // 5.7. CRIAR RESULTADO EDITORIAL
  // ----------------------------------------------------------

  resultados.push({

    json: {

      projeto: CONFIG.projeto,

      versao: CONFIG.versao,

      tipo_registro: "ANALISE_FONTE_HTTP",

      indice_consulta: indice,

      indice_origem: indiceOriginal,

      indice_noticia:
        metadados.indice_noticia ?? null,

      noticias_relacionadas:
        metadados.noticias_relacionadas || [],

      titulo_noticia:
        metadados.titulo_noticia || "",

      titulo_fonte:
        metadados.titulo_fonte || "",

      nome_fonte:
        metadados.nome_fonte || "",

      tipo_fonte:
        metadados.tipo_fonte || "",

      url_consulta: urlConsulta,
      discovery_url: metadados.discovery_url || urlConsulta,
      original_google_news: metadados.original_google_news === true,

      dominio: dominio,

      link_google_news:
        Boolean(metadados.link_google_news),

      resposta_http: {

        status_code:
          Number.isFinite(statusCode)
            ? statusCode
            : null,

        status_message:
          resposta.statusMessage || "",

        content_type:
          headers["content-type"] ||
          headers["Content-Type"] ||
          "",

        tamanho_resposta:
          html.length,

        titulo_html:
          tituloHTML

      },

      analise_fonte: {

        classificacao:
          classificacao.status,

        pagina_acessivel:
          classificacao.acessivel,

        motivo:
          classificacao.motivo,

        texto_extraido:
          textoExtraido,

        exige_verificacao_adicional: true

      },

      seguranca: {

        fonte_autenticada: false,

        conteudo_verificado: false,

        aprovado_para_producao: false,

        aprovado_para_publicacao: false,

        motivo_bloqueio:
          "A confirmação factual da notícia ainda não foi concluída."

      }

    },

    pairedItem: {
      item: indice
    }

  });

}


// ------------------------------------------------------------
// 6. ADICIONAR RESUMO
// ------------------------------------------------------------

for (const resultado of resultados) {

  resultado.json.diagnostico_resumo = {
    ...resumo
  };

}


// ------------------------------------------------------------
// 7. RETORNAR RESULTADOS
// ------------------------------------------------------------

return resultados;

// ============================================================
// VICESCOPE - RECUPERADOR DE EVIDÊNCIAS V1.0
// ============================================================
//
// Recupera conteúdo disponível nos RSS originais.
//
// Fontes:
// - RSS Read1: GameSpot
// - RSS Read2: Google Notícias
//
// NÃO confirma automaticamente nenhuma notícia.
// NÃO libera produção ou publicação.
//
// n8n: Run Once for All Items
// ============================================================

const CONFIG = {
  projeto: "ViceScope",
  versao: "1.0",
  maxCaracteres: 5000,
  minimoCaracteres: 80
};

// ------------------------------------------------------------
// 1. ENTRADAS
// ------------------------------------------------------------

const analises = $input.all();

function lerNo(nome) {
  try {
    return $(nome).all().map(item => item.json || {});
  } catch (erro) {
    return [];
  }
}

const rssGameSpot = lerNo("RSS Read1");
const rssGoogle = lerNo("RSS Read2");

// ------------------------------------------------------------
// 2. FUNÇÕES AUXILIARES
// ------------------------------------------------------------

function str(valor) {
  if (valor === null || valor === undefined) {
    return "";
  }

  return String(valor);
}

function normalizar(valor) {
  return str(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function limparHTML(valor) {
  return str(valor)
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function obterConteudoRSS(item) {
  const campos = [
    "content:encoded",
    "contentEncoded",
    "content",
    "description",
    "summary",
    "contentSnippet"
  ];

  for (const campo of campos) {
    const valor = item[campo];

    if (typeof valor === "string" && valor.trim()) {
      return {
        campo,
        texto: limparHTML(valor).slice(
          0,
          CONFIG.maxCaracteres
        )
      };
    }

    if (
      valor &&
      typeof valor === "object" &&
      typeof valor._ === "string"
    ) {
      return {
        campo,
        texto: limparHTML(valor._).slice(
          0,
          CONFIG.maxCaracteres
        )
      };
    }
  }

  return {
    campo: "",
    texto: ""
  };
}

function removerBarraFinal(url) {
  return str(url)
    .trim()
    .replace(/\/+$/, "");
}

function encontrarRSS(fonte, colecao) {
  const urlProcurada = removerBarraFinal(
    fonte.discovery_url || fonte.url_consulta
  );

  const tituloProcurado = normalizar(
    fonte.titulo_fonte
  );

  // Prioridade 1: URL exata.
  if (urlProcurada) {
    const encontradoURL = colecao.find(item =>
      removerBarraFinal(item.link) === urlProcurada
    );

    if (encontradoURL) {
      return {
        item: encontradoURL,
        metodo: "URL_EXATA"
      };
    }
  }

  // Prioridade 2: título normalizado exato.
  // Não utiliza semelhança aproximada para evitar
  // associar o conteúdo de notícias diferentes.
  if (tituloProcurado) {
    const encontrados = colecao.filter(item =>
      normalizar(item.title) === tituloProcurado
    );

    if (encontrados.length === 1) {
      return {
        item: encontrados[0],
        metodo: "TITULO_EXATO"
      };
    }
  }

  return {
    item: null,
    metodo: "NAO_ENCONTRADO"
  };
}

// ------------------------------------------------------------
// 3. PROCESSAR FONTES
// ------------------------------------------------------------

const resultados = [];

const resumo = {
  total_fontes: analises.length,
  rss_encontrado: 0,
  rss_nao_encontrado: 0,
  conteudo_disponivel: 0,
  conteudo_insuficiente: 0,
  artigos_http_acessiveis: 0,
  fontes_factualmente_verificadas: 0,
  aprovadas_para_producao: 0,
  aprovadas_para_publicacao: 0
};

for (let i = 0; i < analises.length; i++) {
  const entrada = analises[i].json || {};

  const origemGoogle = Boolean(
    entrada.original_google_news || entrada.link_google_news
  );

  const colecao = origemGoogle
    ? rssGoogle
    : rssGameSpot;

  const busca = encontrarRSS(
    entrada,
    colecao
  );

  const rss = busca.item;

  if (rss) {
    resumo.rss_encontrado++;
  } else {
    resumo.rss_nao_encontrado++;
  }

  let conteudo = rss
    ? obterConteudoRSS(rss)
    : { campo: "", texto: "" };

  const httpText = limparHTML(entrada.analise_fonte?.texto_extraido || '');
  const httpUsable = entrada.analise_fonte?.classificacao === 'ARTIGO_ACESSIVEL' &&
    !entrada.link_google_news && httpText.length >= 250;
  if (httpUsable && httpText.length > conteudo.texto.length) {
    conteudo = {campo: 'http.texto_extraido', texto: httpText.slice(0, CONFIG.maxCaracteres)};
  }

  const temConteudo =
    conteudo.texto.length >=
    CONFIG.minimoCaracteres;

  if (temConteudo) {
    resumo.conteudo_disponivel++;
  } else {
    resumo.conteudo_insuficiente++;
  }

  const httpAcessivel =
    entrada.analise_fonte?.classificacao ===
    "ARTIGO_ACESSIVEL";

  if (httpAcessivel) {
    resumo.artigos_http_acessiveis++;
  }

  let status = "SEM_EVIDENCIA_TEXTUAL";

  if (temConteudo) {
    status = conteudo.campo === "http.texto_extraido" ? "TEXTO_HTTP_DISPONIVEL" : "TEXTO_RSS_DISPONIVEL";
  } else if (rss) {
    status = "RSS_SEM_TEXTO_SUFICIENTE";
  }

  resultados.push({
    json: {
      projeto: CONFIG.projeto,
      versao: CONFIG.versao,
      tipo_registro: "EVIDENCIA_RECUPERADA",

      indice_consulta:
        entrada.indice_consulta ?? i,

      indice_noticia:
        entrada.indice_noticia ?? null,

      noticias_relacionadas:
        entrada.noticias_relacionadas || [],

      titulo_noticia:
        entrada.titulo_noticia || "",

      titulo_fonte:
        entrada.titulo_fonte || "",

      nome_fonte:
        entrada.nome_fonte || "",

      tipo_fonte:
        entrada.tipo_fonte || "",

      url_consulta:
        entrada.url_consulta || "",

      dominio:
        entrada.dominio || "",

      resposta_http:
        entrada.resposta_http || {},

      analise_http:
        entrada.analise_fonte || {},

      evidencia: {
        artigo_original_acessado: httpUsable,
        url_original_resolvida: !entrada.link_google_news && ["http://", "https://"].some(prefix => String(entrada.url_consulta || "").startsWith(prefix)),
        verificacao_factual_concluida: false,
        status,

        origem:
          conteudo.campo === "http.texto_extraido" ? "HTTP_ARTIGO" : rss
            ? origemGoogle
              ? "GOOGLE_NEWS_RSS"
              : "GAMESPOT_RSS"
            : "NAO_ENCONTRADA",

        metodo_correspondencia:
          busca.metodo,

        titulo_rss:
          rss ? str(rss.title) : "",

        url_rss:
          rss ? str(rss.link) : "",

        data_publicacao:
          rss
            ? str(
                rss.isoDate ||
                rss.pubDate ||
                ""
              )
            : "",

        campo_conteudo:
          conteudo.campo,

        texto:
          conteudo.texto,

        tamanho_texto:
          conteudo.texto.length,

        texto_disponivel:
          temConteudo,

        observacao:
          "Texto obtido do RSS. Não representa confirmação independente dos fatos."
      },

      seguranca: {
        fonte_autenticada: false,
        conteudo_verificado: false,
        aprovado_para_producao: false,
        aprovado_para_publicacao: false,

        exige_verificacao_factual: true,

        motivo_bloqueio:
          "A evidência RSS ainda precisa de validação factual e editorial."
      }
    },

    pairedItem: {
      item: i
    }
  });
}

// ------------------------------------------------------------
// 4. RESUMO
// ------------------------------------------------------------

for (const resultado of resultados) {
  resultado.json.diagnostico_resumo = {
    ...resumo
  };
}

// ------------------------------------------------------------
// 5. SAÍDA
// ------------------------------------------------------------

return resultados;

// ============================================================
// VICESCOPE - SELETOR DE NOTÍCIAS V1.0
// ============================================================
//
// Agrupa fontes por notícia.
// Seleciona uma notícia candidata para roteiro.
// Bloqueia automaticamente rumores e vazamentos.
//
// IMPORTANTE:
// Seleção para análise NÃO significa aprovação factual.
//
// n8n: Run Once for All Items
// ============================================================

const entradas = $input.all();

const CONFIG = {
  projeto: "ViceScope",
  versao: "1.0",
  idioma: "en-US",
  duracao_segundos: 40,
  minimo_texto_principal: 250,
  maximo_fontes: 8,
  maximo_texto_fonte: 3500
};

// ------------------------------------------------------------
// FUNÇÕES
// ------------------------------------------------------------

function texto(valor) {
  return valor === null || valor === undefined
    ? ""
    : String(valor);
}

function normalizar(valor) {
  return texto(valor)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function detectarRisco(conteudo) {
  const termos = [
    /\bleak(s|ed|er)?\b/i,
    /\brumou?r(s|ed)?\b/i,
    /\balleged(ly)?\b/i,
    /\bunconfirmed\b/i,
    /\bspeculation\b/i,
    /\bcyberleek\b/i,
    /\bsupposed(ly)?\b/i
  ];

  return termos.some(regra => regra.test(conteudo));
}

// ------------------------------------------------------------
// AGRUPAR POR NOTÍCIA
// ------------------------------------------------------------

const grupos = {};

for (const item of entradas) {
  const dado = item.json || {};

  const id = dado.indice_noticia;

  if (id === null || id === undefined) {
    continue;
  }

  const chave = String(id);

  if (!grupos[chave]) {
    grupos[chave] = {
      indice_noticia: id,
      titulo: dado.titulo_noticia || "",
      fontes: []
    };
  }

  grupos[chave].fontes.push({
    nome: dado.nome_fonte || "",
    tipo: dado.tipo_fonte || "",
    titulo: dado.titulo_fonte || "",
    url: dado.url_consulta || "",
    data: dado.evidencia?.data_publicacao || "",
    origem: dado.evidencia?.origem || "",
    texto: texto(dado.evidencia?.texto).slice(
      0,
      CONFIG.maximo_texto_fonte
    ),
    texto_disponivel:
      dado.evidencia?.texto_disponivel === true,
    artigo_original_acessado: dado.evidencia?.artigo_original_acessado === true,
    url_original_resolvida: dado.evidencia?.url_original_resolvida === true,
    verificacao_factual_concluida: false
  });
}

// ------------------------------------------------------------
// CLASSIFICAR CANDIDATOS
// ------------------------------------------------------------

const candidatos = [];

for (const grupo of Object.values(grupos)) {
  const principal = grupo.fontes.find(
    fonte => fonte.tipo === "FONTE_PRINCIPAL"
  );

  const textoPrincipal = texto(principal?.texto);

  const tituloPrincipal = texto(grupo.titulo);

  const risco = detectarRisco(
    tituloPrincipal + " " + textoPrincipal
  );

  const temTextoPrincipal =
    textoPrincipal.length >=
    CONFIG.minimo_texto_principal;

  const fontesDistintas = [
    ...new Set(
      grupo.fontes
        .map(f => normalizar(f.nome))
        .filter(Boolean)
    )
  ].length;

  const elegivelParaRoteiro =
    Boolean(principal) &&
    temTextoPrincipal &&
    !risco;

  candidatos.push({
    ...grupo,
    principal,
    risco,
    tem_texto_principal: temTextoPrincipal,
    fontes_distintas: fontesDistintas,
    elegivel_para_roteiro: elegivelParaRoteiro,
    pontuacao:
      (temTextoPrincipal ? 100 : 0) +
      fontesDistintas * 10 -
      (risco ? 1000 : 0)
  });
}

// ------------------------------------------------------------
// ESCOLHER UM CANDIDATO
// ------------------------------------------------------------

const elegiveis = candidatos
  .filter(c => c.elegivel_para_roteiro)
  .sort((a, b) => b.pontuacao - a.pontuacao);

if (elegiveis.length === 0) {
  return [{
    json: {
      projeto: CONFIG.projeto,
      tipo_registro: "SEM_NOTICIA_ELEGIVEL",
      motivo:
        "Nenhuma notícia possui texto principal suficiente e risco editorial aceitável.",
      total_grupos: candidatos.length,
      aprovado_para_producao: false,
      aprovado_para_publicacao: false
    }
  }];
}

const selecionada = elegiveis[0];

// ------------------------------------------------------------
// PREPARAR PACOTE PARA O GEMINI
// ------------------------------------------------------------

const fontes = selecionada.fontes
  .slice(0, CONFIG.maximo_fontes)
  .map(f => ({
    nome: f.nome,
    tipo: f.tipo,
    titulo: f.titulo,
    url: f.url,
    data: f.data,
    origem: f.origem,
    texto: f.texto,
    artigo_original_acessado: f.artigo_original_acessado,
    url_original_resolvida: f.url_original_resolvida,
    verificacao_factual_concluida: false
  }));

return [{
  json: {
    projeto: CONFIG.projeto,
    versao: CONFIG.versao,

    tipo_registro: "CANDIDATO_ROTEIRO",

    indice_noticia:
      selecionada.indice_noticia,

    titulo:
      selecionada.titulo,

    idioma:
      CONFIG.idioma,

    duracao_segundos:
      CONFIG.duracao_segundos,

    total_fontes:
      fontes.length,

    fontes_distintas:
      selecionada.fontes_distintas,

    fontes,

    verificacao: {
      risco_detectado: false,
      texto_principal_disponivel: true,
      verificacao_factual_concluida: false,
      pronto_para_analise_gemini: true
    },

    seguranca: {
      aprovado_para_producao: false,
      aprovado_para_publicacao: false,
      exige_revisao_editorial: true
    }
  }
}];

const entries = $input.all();
const results = [];

function asText(value) {
  return value === null || value === undefined ? '' : String(value);
}

function cleanModelText(value) {
  return asText(value)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
}

function safeJsonParse(value) {
  const cleaned = cleanModelText(value);
  try {
    return JSON.parse(cleaned);
  } catch {
    const first = cleaned.indexOf('{');
    const last = cleaned.lastIndexOf('}');
    if (first >= 0 && last > first) {
      return JSON.parse(cleaned.slice(first, last + 1));
    }
    throw new Error('O modelo não retornou um objeto JSON válido.');
  }
}

function compact(value) {
  return asText(value).replace(/\s+/g, ' ').trim();
}

function wordCount(value) {
  const normalized = compact(value);
  return normalized ? normalized.split(' ').length : 0;
}

function limitText(value, max) {
  const normalized = compact(value);
  if (normalized.length <= max) return normalized;
  const shortened = normalized.slice(0, max + 1);
  const boundary = shortened.lastIndexOf(' ');
  return (boundary > 20 ? shortened.slice(0, boundary) : shortened.slice(0, max)).trim();
}

let editorialPackage = {};
try {
  editorialPackage = $('Executar Mestre Editorial').first().json || {};
} catch {
  editorialPackage = {};
}

const editorialEntry = Array.isArray(editorialPackage.packages)
  ? editorialPackage.packages[0] || {}
  : {};

for (const entry of entries) {
  const response = entry.json || {};

  let raw = '';
  if (response.content?.parts?.length) {
    raw = response.content.parts.map(part => part.text || '').join('\n');
  }
  if (!raw && typeof response.text === 'string') raw = response.text;
  if (!raw && typeof response.output === 'string') raw = response.output;
  if (!raw && response.roteiro) raw = JSON.stringify(response);

  if (!raw && response.candidates?.[0]?.content?.parts) {
    raw = response.candidates[0].content.parts.map(part => part.text || '').join('\n');
  }
  if (!raw && response.content && !response.content.parts && typeof response.content === 'object') {
    raw = JSON.stringify(response.content);
  }
  if (!raw && response.output && typeof response.output === 'object') {
    raw = JSON.stringify(response.output);
  }

  let draft;
  try {
    draft = safeJsonParse(raw);
  } catch (error) {
    results.push({
      json: {
        schemaVersion: '3.1',
        status: 'REVIEW_REQUIRED',
        reason: 'INVALID_MODEL_JSON',
        error: error.message,
        manualApprovalRequired: true,
        noAutomaticPublishing: true
      }
    });
    continue;
  }

  const modelStatus = compact(draft.status).toUpperCase();
  const script = draft.roteiro || {};
  const narration = compact(
    script.narracao_completa ||
    [script.hook, script.body, script.ending].filter(Boolean).join(' ')
  );

  const words = wordCount(narration);
  const narrationLengthValid = words >= 65 && words <= 105;
  const narrationCharactersValid = narration.length > 0 && narration.length <= 1200;
  const requestedReview = ['REVIEW_REQUIRED', 'NEEDS_REVIEW'].includes(modelStatus);
  const hasPendingClaims = Array.isArray(draft.verificacao?.afirmacoes_pendentes) &&
    draft.verificacao.afirmacoes_pendentes.length > 0;
  const modelReportedIndependentVerification =
    draft.verificacao?.verificacao_independente_concluida === true ||
    draft.verificacao?.verificacao_independent_concluida === true;

  // O modelo não comprova que URLs foram acessadas ou fontes autenticadas.
  const independentVerification = false;
  const titleText = compact(draft.titulo_video);
  const subtitleText = compact(script.hook || draft.selected_hook);
  const titleLengthValid = titleText.length > 0 && titleText.length <= 50;
  const subtitleLengthValid = subtitleText.length > 0 && subtitleText.length <= 70;
  const modelStatusValid = modelStatus === 'DRAFT_READY';
  const languageValid = compact(draft.idioma) === 'en-US';
  const completionReason = response.finishReason || response.candidates?.[0]?.finishReason;
  const completionValid = !completionReason || completionReason === 'STOP';
  const safetyValid = draft.seguranca?.aprovado_para_producao === false &&
    draft.seguranca?.aprovado_para_publicacao === false &&
    draft.seguranca?.exige_revisao_editorial === true;

  const readyForHumanReview =
    titleLengthValid && subtitleLengthValid && modelStatusValid &&
    languageValid && completionValid && safetyValid &&
    !requestedReview &&
    narrationLengthValid &&
    narrationCharactersValid &&
    Boolean(compact(draft.titulo_video)) &&
    narration.length > 0;

  const factualReviewComplete = independentVerification && !hasPendingClaims;
  const status = !readyForHumanReview ? 'REVIEW_REQUIRED'
    : !factualReviewComplete ? 'AWAITING_FACTUAL_REVIEW'
    : 'READY_FOR_HUMAN_REVIEW';

  const reviewReasons = [];
  if (!titleLengthValid) reviewReasons.push('TITLE_LENGTH_INVALID');
  if (!subtitleLengthValid) reviewReasons.push('SUBTITLE_LENGTH_INVALID');
  if (!modelStatusValid) reviewReasons.push('MODEL_STATUS_NOT_DRAFT_READY');
  if (!languageValid) reviewReasons.push('LANGUAGE_NOT_EN_US');
  if (!completionValid) reviewReasons.push('MODEL_RESPONSE_INCOMPLETE');
  if (!safetyValid) reviewReasons.push('MODEL_SAFETY_FLAGS_INVALID');
  if (requestedReview) reviewReasons.push('MODEL_REQUESTED_REVIEW');
  if (!narrationLengthValid) reviewReasons.push('NARRATION_WORD_COUNT_OUT_OF_RANGE');
  if (!narrationCharactersValid) reviewReasons.push('NARRATION_CHARACTER_LIMIT_FAILED');
  if (!compact(draft.titulo_video)) reviewReasons.push('MISSING_TITLE');
  if (hasPendingClaims) reviewReasons.push('PENDING_FACTUAL_CLAIMS');
  if (!independentVerification) reviewReasons.push('INDEPENDENT_VERIFICATION_NOT_CONFIRMED');

  const candidate = editorialEntry.candidate || {};
  const creativeBrief = editorialEntry.creativeBrief || {};

  results.push({
    json: {
      schemaVersion: '3.1',
      project: 'ViceScope',
      status,
      generatedAt: new Date().toISOString(),
      language: compact(draft.idioma || 'en-US'),
      category: compact(draft.category || candidate.topic || 'NEWS'),
      candidateId: compact(editorialEntry.candidateId || candidate.candidateId),
      title: titleText,
      subtitle: subtitleText,
      narration,
      wordCount: words,
      estimatedDurationSeconds: Number(
        draft.duracao_estimada_segundos || Math.round(words / 2.35)
      ),
      scenes: Array.isArray(draft.cenas) ? draft.cenas : [],
      description: compact(draft.description || ''),
      hashtags: Array.isArray(draft.hashtags) ? draft.hashtags.slice(0, 8) : [],
      source: {
        title: compact(candidate.title || candidate.titulo),
        publisher: compact(candidate.publisher),
        url: compact(candidate.discoveryUrl || candidate.url),
        publishedAt: compact(candidate.publishedAt),
        official: candidate.official === true,
        reliability: compact(candidate.reliability),
        riskFlags: Array.isArray(candidate.riskFlags) ? candidate.riskFlags : [],
        evidenceSources: Array.isArray(candidate.evidenceSources)
          ? candidate.evidenceSources
          : []
      },
      creativeBrief,
      sourceReviewQueue: (Array.isArray(candidate.evidenceSources) ? candidate.evidenceSources : []).map(source => {
        const url = compact(source.url);
        const discovery = /^https?:\/\/news\.google\.com\//i.test(url);
        return {
          name: compact(source.nome),
          url,
          origin: compact(source.origem),
          originalUrlResolved: source.url_original_resolvida === true && !discovery,
          originalArticleAccessed: source.artigo_original_acessado === true && !discovery,
          nextAction: discovery ? 'RESOLVE_ORIGINAL_URL'
            : source.artigo_original_acessado !== true ? 'FETCH_ORIGINAL_ARTICLE'
