function texto(valor) {

  if (typeof valor === "string") {
    return valor.trim();
  }

  return "";

}


function primeiroTexto(...valores) {

  for (const valor of valores) {

    const resultado = texto(valor);

    if (resultado) {
      return resultado;
    }

  }

  return "";

}


function normalizar(valor) {

  return texto(valor)
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

}


function palavrasRelevantes(valor) {

  const palavras = normalizar(valor).split(" ");

  return [...new Set(
    palavras.filter(palavra => {

      return (
        palavra.length >= 3 &&
        !CONFIG.palavrasIgnoradas.includes(palavra)
      );

    })
  )];

}


// ============================================================
