  });

}


// ============================================================
// 13. CRUZAMENTO DE NOTÍCIAS
// ============================================================

const resultados = [];


for (const item of noticiasOriginais) {

  const noticia = item.json || {};

  const dadosNoticia = noticia.noticia || {};

  const tituloOriginal = primeiroTexto(
    dadosNoticia.titulo,
    dadosNoticia.Titulo,
    dadosNoticia["título"]
  );

  const fonteOriginal = primeiroTexto(
    dadosNoticia.fonte,
    noticia.fonte
  );

  const assuntosOriginais =
    identificarAssuntos(tituloOriginal);

  const correspondencias = [];


  for (const fonteGoogle of noticiasGoogle) {

    const comparacaoAssunto =
      compararAssuntos(
        tituloOriginal,
        fonteGoogle.titulo
      );

    const comparacaoDetalhes =
      compararDetalhes(
        tituloOriginal,
        fonteGoogle.titulo
      );

    const pontuacao =
      calcularSimilaridade(
        tituloOriginal,
        fonteGoogle.titulo
      );


    // Não comparar a notícia com o mesmo veículo

    if (
      normalizar(fonteGoogle.fonte) ===
      normalizar(fonteOriginal)
    ) {
      continue;
    }


    // Não aceitar conflitos conhecidos

    if (comparacaoDetalhes.possui_conflito) {
      continue;
    }


    // Exigir assunto em comum OU similaridade relevante

    if (
      !comparacaoAssunto.assunto_compativel &&
      pontuacao < CONFIG.similaridadeMinima
    ) {
      continue;
    }


    // Pontuação de triagem, não de veracidade

    let pontuacaoTriagem =
      pontuacao * 100;


    if (
      comparacaoAssunto.assunto_compativel
    ) {

      pontuacaoTriagem += 15;

    }


    pontuacaoTriagem +=
      comparacaoDetalhes.coincidencias.length * 15;


    pontuacaoTriagem = Math.min(
      100,
      Math.round(pontuacaoTriagem)
    );


    correspondencias.push({

      ...fonteGoogle,

      similaridade_titulo:
        Math.round(pontuacao * 100),

      pontuacao_triagem:
        pontuacaoTriagem,

      comparacao_assuntos:
        comparacaoAssunto,

      comparacao_detalhes:
        comparacaoDetalhes,

      status_evidencia:
        "CANDIDATO_NAO_VERIFICADO"

    });

  }


  // ==========================================================
  // 14. ORDENAR CORRESPONDÊNCIAS
  // ==========================================================

  correspondencias.sort(
    (a, b) =>
      b.pontuacao_triagem -
      a.pontuacao_triagem
  );


  // ==========================================================
  // 15. REMOVER VEÍCULOS DUPLICADOS
  // ==========================================================

  const fontesUnicas = [];

  const fontesRegistradas = new Set();


  for (const fonte of correspondencias) {

    const identificador =
      normalizar(fonte.fonte);

    if (
      fontesRegistradas.has(identificador)
    ) {
      continue;
    }

    fontesRegistradas.add(identificador);

    fontesUnicas.push(fonte);

    if (
      fontesUnicas.length >=
      CONFIG.maxFontesPorNoticia
    ) {
      break;
    }

  }


  // ==========================================================
  // 16. PREPARAR CANDIDATOS PARA GEMINI
  // ==========================================================

  const candidatosGemini =
    fontesUnicas
      .slice(
        0,
        CONFIG.maxCandidatosGemini
      )
      .map(fonte => ({

        titulo: fonte.titulo,

        fonte: fonte.fonte,

        link: fonte.link,

        data: fonte.data,

        assuntos:
          fonte.assuntos,

        pontuacao_triagem:
          fonte.pontuacao_triagem,

        comparacao_detalhes:
          fonte.comparacao_detalhes

      }));


  // ==========================================================
  // 17. CONTAR FONTES
  // ==========================================================

  const fontesPrimarias =
    fontesUnicas.filter(
      fonte =>
        fonte.categoria_origem ===
        "FONTE_PRIMARIA_POTENCIAL"
    );


  const fontesJornalisticas =
    fontesUnicas.filter(
      fonte =>
        fonte.categoria_origem ===
        "VEICULO_JORNALISTICO"
    );


  // ==========================================================
  // 18. RESULTADO FINAL
  // ==========================================================

  resultados.push({

    json: {

      ...noticia,

      inteligencia_assuntos: {

        versao: CONFIG.versao,

        assuntos_identificados:
          assuntosOriginais,

        titulo_analisado:
          tituloOriginal

      },

      cruzamento_fontes: {

        versao: CONFIG.versao,

        classificador_recuperado_de:
          nomeClassificador,

        total_resultados_pesquisados:
          noticiasGoogle.length,

        total_candidatos_brutos:
          correspondencias.length,

        total_fontes_relacionadas:
          fontesUnicas.length,

        fontes_primarias_potenciais:
          fontesPrimarias.length,

        veiculos_jornalisticos:
          fontesJornalisticas.length,

        fontes_encontradas:
          fontesUnicas,

        status:
          fontesUnicas.length > 0
            ? "CANDIDATOS_ENCONTRADOS"
            : "SEM_CANDIDATOS",

        verificacao_independente_concluida:
          false,

        observacao:
          "Correspondencias por assunto, detalhes " +
          "e similaridade. Ainda nao verificadas."

      },

      preparacao_gemini: {

        status:
          candidatosGemini.length > 0
            ? "PRONTO_PARA_ANALISE"
            : "SEM_CANDIDATOS",

        objetivo:
          "IDENTIFICAR_MESMO_ACONTECIMENTO",

        titulo_original:
          tituloOriginal,

        candidatos:
          candidatosGemini,

        total_candidatos:
          candidatosGemini.length,

        analise_executada: false

      },

      verificacao: {

        ...(noticia.verificacao || {}),

        status:
          "AGUARDANDO_ANALISE_DAS_EVIDENCIAS",

        fontes_independentes_verificadas: 0,

        confirmacao_oficial: false

      },

      seguranca: {

        ...(noticia.seguranca || {}),

        aprovado_para_producao: false,

        aprovado_para_publicacao: false,

        motivo_bloqueio:
          "EVIDENCIAS_AINDA_NAO_VERIFICADAS"

      },

      proxima_etapa:
        "COMPARAR_ACONTECIMENTOS_COM_GEMINI"

    }

  });

}


// ============================================================
