// ============================================================
// 1. CONFIGURAÇÕES
// ============================================================

const CONFIG = {

  projeto: "ViceScope",

  versao: "1.1",

  nomeOrigem: "Code in JavaScript4",

  limiarCorrespondencia: 80,

  classificacoesPermitidas: [
    "SAME_EVENT",
    "RELATED_BUT_DIFFERENT",
    "UNRELATED",
    "UNCERTAIN"
  ]

};


// ============================================================
// 2. FUNÇÕES AUXILIARES
// ============================================================

function texto(valor) {

  if (valor === null || valor === undefined) {
    return "";
  }

  return String(valor).trim();

}


function objeto(valor) {

  return (
    valor !== null &&
    typeof valor === "object" &&
    !Array.isArray(valor)
  )
    ? valor
    : {};

}


function lista(valor) {

  return Array.isArray(valor)
    ? valor
    : [];

}


function numero(valor, padrao = 0) {

  if (
    valor === null ||
    valor === undefined ||
    valor === ""
  ) {
    return padrao;
  }

  const resultado = Number(valor);

  return Number.isFinite(resultado)
    ? resultado
    : padrao;

}


function normalizar(valor) {

  return texto(valor)
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

}


function limitar(valor, minimo, maximo) {

  return Math.min(
    maximo,
    Math.max(minimo, valor)
  );

}


// ============================================================
// 3. EXTRAIR RESPOSTA DO GEMINI
// ============================================================

function extrairGemini(item) {

  const dados = objeto(item.json);

  if (
    dados.versao &&
    Array.isArray(dados.resultados)
  ) {
    return dados;
  }

  const campos = [
    dados.text,
    dados.output,
    dados.response,
    dados.content
  ];

  for (const campo of campos) {

    if (typeof campo === "string" && campo.trim()) {
      return campo;
    }

  }

  const candidatos = lista(dados.candidates);

  for (const candidato of candidatos) {

    const partes = lista(
      candidato?.content?.parts
    );

    const conteudo = partes
      .map(parte => parte?.text)
      .filter(parte => typeof parte === "string")
      .join("\n");

    if (conteudo) {
      return conteudo;
    }

  }

  const partesDiretas = lista(
    dados.content?.parts
  );

  if (partesDiretas.length > 0) {

    return partesDiretas
      .map(parte => parte?.text)
      .filter(parte => typeof parte === "string")
      .join("\n");

  }

  throw new Error(
    "RESPOSTA_GEMINI_NAO_ENCONTRADA"
  );

}


// ============================================================
// 4. INTERPRETAR JSON
// ============================================================

function interpretarJSON(resposta) {

  if (
    resposta &&
    typeof resposta === "object"
  ) {
    return resposta;
  }

  let conteudo = texto(resposta);

  if (!conteudo) {

    throw new Error(
      "RESPOSTA_GEMINI_VAZIA"
    );

  }

  conteudo = conteudo
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {

    return JSON.parse(conteudo);

  } catch (erro) {

    const inicio = conteudo.indexOf("{");
    const fim = conteudo.lastIndexOf("}");

    if (inicio >= 0 && fim > inicio) {

      return JSON.parse(
        conteudo.slice(inicio, fim + 1)
      );

    }

    throw new Error(
      "JSON_GEMINI_INVALIDO"
    );

  }

}


// ============================================================
// 5. RECUPERAR NOTÍCIAS ORIGINAIS
// ============================================================

let noticiasOriginais = [];

let erroOrigem = null;

try {

  noticiasOriginais = $(
    CONFIG.nomeOrigem
  ).all();

} catch (erro) {

  erroOrigem = erro.message;

}


// ============================================================
// 6. RECEBER RESPOSTAS DO GEMINI
// ============================================================

const respostasGemini = $input.all();

const resultadosFinais = [];


// ============================================================
// 7. PROCESSAR NOTÍCIAS
// ============================================================

for (
  let indiceNoticia = 0;
  indiceNoticia < respostasGemini.length;
  indiceNoticia++
) {

  const itemGemini =
    respostasGemini[indiceNoticia];

  const origem = objeto(
    noticiasOriginais[indiceNoticia]?.json
  );

  const erros = [];
  const alertas = [];

  let analiseGemini = {};

  let jsonGeminiValido = false;


  // ==========================================================
  // 8. INTERPRETAR RESPOSTA
  // ==========================================================

  try {

    const resposta = extrairGemini(
      itemGemini
    );

    analiseGemini = objeto(
      interpretarJSON(resposta)
    );

    jsonGeminiValido = true;

  } catch (erro) {

    erros.push(
      "ERRO_JSON_GEMINI: " + erro.message
    );

  }


  // ==========================================================
  // 9. VALIDAR NOTÍCIA ORIGINAL
  // ==========================================================

  if (erroOrigem) {

    erros.push(
      "ERRO_ORIGEM: " + erroOrigem
    );

  }

  if (!origem.noticia) {

    erros.push(
      "NOTICIA_ORIGINAL_NAO_ENCONTRADA"
    );

  }

  const noticia = objeto(
    origem.noticia
  );

  const tituloOriginal = texto(
    noticia.titulo ||
    noticia.Titulo ||
    noticia["título"]
  );

  const tituloGemini = texto(
    analiseGemini.titulo_original
  );

  if (!tituloOriginal) {

    erros.push(
      "TITULO_ORIGINAL_AUSENTE"
    );

  }

  if (!tituloGemini) {

    erros.push(
      "TITULO_GEMINI_AUSENTE"
    );

  }

  if (
    tituloOriginal &&
    tituloGemini &&
    normalizar(tituloOriginal) !==
    normalizar(tituloGemini)
  ) {

    erros.push(
      "TITULO_ORIGINAL_DIVERGENTE"
    );

  }


  // ==========================================================
  // 10. RECUPERAR CANDIDATOS
  // ==========================================================

  const preparacao = objeto(
    origem.preparacao_gemini
  );

  const candidatosOriginais = lista(
    preparacao.candidatos
  );

  const resultadosGemini = lista(
    analiseGemini.resultados
  );

  if (!Array.isArray(analiseGemini.resultados)) {

    erros.push(
      "RESULTADOS_GEMINI_INVALIDOS"
    );

  }

  if (
    candidatosOriginais.length !==
    resultadosGemini.length
  ) {

    erros.push(
      "QUANTIDADE_CANDIDATOS_DIVERGENTE"
    );

  }

  if (
    numero(
      analiseGemini.candidatos_analisados,
      -1
    ) !== candidatosOriginais.length
  ) {

    erros.push(
      "CONTAGEM_CANDIDATOS_INCONSISTENTE"
    );

  }


  // ==========================================================
  // 11. VALIDAR CORRESPONDÊNCIAS
  // ==========================================================

  const correspondencias = [];

  const indicesProcessados = new Set();

  for (
    let i = 0;
    i < resultadosGemini.length;
    i++
  ) {

    const resultado = objeto(
      resultadosGemini[i]
    );

    const indice = numero(
      resultado.indice,
      -1
    );

    if (
      !Number.isInteger(indice) ||
      indice < 0 ||
      indice >= candidatosOriginais.length
    ) {

      erros.push(
        `INDICE_INVALIDO_${i}`
      );

      continue;

    }

    if (indicesProcessados.has(indice)) {

      erros.push(
        `INDICE_DUPLICADO_${indice}`
      );

      continue;

    }

    indicesProcessados.add(indice);

    const candidato = objeto(
      candidatosOriginais[indice]
    );

    const tituloCandidato = texto(
      candidato.titulo ||
      candidato.title
    );

    const fonteCandidato = texto(
      candidato.fonte ||
      candidato.source
    );

    const tituloResposta = texto(
      resultado.titulo
    );

    const fonteResposta = texto(
      resultado.fonte
    );

    if (
      normalizar(tituloCandidato) !==
      normalizar(tituloResposta)
    ) {

      erros.push(
        `TITULO_CANDIDATO_DIVERGENTE_${indice}`
      );

    }

    if (
      normalizar(fonteCandidato) !==
      normalizar(fonteResposta)
    ) {

      erros.push(
        `FONTE_CANDIDATO_DIVERGENTE_${indice}`
      );

    }

    const classificacao = texto(
      resultado.classificacao
    ).toUpperCase();

    if (
      !CONFIG.classificacoesPermitidas.includes(
        classificacao
      )
    ) {

      erros.push(
        `CLASSIFICACAO_INVALIDA_${indice}`
      );

    }

    const confianca = limitar(
      numero(
        resultado.confianca_correspondencia
      ),
      0,
      100
    );

    const correspondenciaForte = (
      classificacao === "SAME_EVENT" &&
      confianca >= CONFIG.limiarCorrespondencia
    );

    correspondencias.push({

      indice,

      titulo: tituloCandidato,

      fonte: fonteCandidato,

      link: texto(
        candidato.link ||
        candidato.url
      ),

      classificacao,

      confianca_correspondencia:
        confianca,

      correspondencia_forte:
        correspondenciaForte,

      justificativa: texto(
        resultado.justificativa
      ),

      detalhes_coincidentes: lista(
        resultado.detalhes_coincidentes
      ),

      possiveis_contradicoes: lista(
        resultado.possiveis_contradicoes
      ),

      conteudo_original_verificado: false,

      fonte_independente_verificada: false,

      fonte_oficial_autenticada: false

    });

  }


  // ==========================================================
  // 12. CONTAGENS
  // ==========================================================

  const totalMesmoEvento =
    correspondencias.filter(
      item =>
        item.classificacao === "SAME_EVENT"
    ).length;

  const totalIncertos =
    correspondencias.filter(
      item =>
        item.classificacao === "UNCERTAIN"
    ).length;

  const totalFortes =
    correspondencias.filter(
      item =>
        item.correspondencia_forte
    ).length;


  if (
    numero(
      analiseGemini.total_mesmo_acontecimento,
      -1
    ) !== totalMesmoEvento
  ) {

    erros.push(
      "TOTAL_MESMO_EVENTO_INCONSISTENTE"
    );

  }

  if (
    numero(
      analiseGemini.total_incertos,
      -1
    ) !== totalIncertos
  ) {

    erros.push(
      "TOTAL_INCERTOS_INCONSISTENTE"
    );

  }


  // ==========================================================
  // 13. DETECTAR RISCO EDITORIAL
  // ==========================================================

  const analiseOriginal = objeto(
    origem.analise
  );

  const riscoOriginal = texto(
    analiseOriginal.risco_editorial
  );

  const textoRisco = normalizar(
    [
      tituloOriginal,
      riscoOriginal,
      analiseOriginal.tipo_conteudo,
      analiseOriginal.classificacao_preliminar
    ].join(" ")
  );

  const riscoVazamento =
    /\b(leak|leaks|leaked|rumor|rumors|vazamento|boato)\b/
      .test(textoRisco);

  const riscoAlto =
    /\b(high|alto|critical|critico)\b/
      .test(normalizar(riscoOriginal));

  const riscoElevado =
    riscoVazamento || riscoAlto;

  if (riscoElevado) {

    alertas.push(
      "RISCO_EDITORIAL_ELEVADO"
    );

  }

  if (candidatosOriginais.length === 0) {

    alertas.push(
      "SEM_CANDIDATOS"
    );

  }

  if (totalMesmoEvento === 0) {

    alertas.push(
      "SEM_CORRESPONDENCIAS_CONFIRMADAS"
    );

  }


  // ==========================================================
  // 14. IMPEDIR APROVAÇÃO INDEVIDA
  // ==========================================================

  if (
    analiseGemini.aprovado_para_producao === true ||
    analiseGemini.aprovado_para_publicacao === true ||
    analiseGemini.confirmacao_oficial === true ||
    numero(
      analiseGemini.fontes_independentes_verificadas
    ) > 0
  ) {

    erros.push(
      "APROVACAO_INDEVIDA_PELO_GEMINI"
    );

  }


  // ==========================================================
  // 15. DEFINIR STATUS
  // ==========================================================

  const validacaoOK = (
    jsonGeminiValido &&
    erros.length === 0
  );

  let status = "ERRO_VALIDACAO";

  if (validacaoOK) {

    if (candidatosOriginais.length === 0) {

      status = "SEM_CANDIDATOS";

    } else if (totalMesmoEvento === 0) {

      status = "SEM_CORRESPONDENCIAS";

    } else if (riscoElevado) {

      status = "REVISAO_EDITORIAL_PRIORITARIA";

    } else {

      status = "AGUARDANDO_VERIFICACAO_DAS_FONTES";

    }

  }


  // ==========================================================
  // 16. RESULTADO FINAL
  // ==========================================================

  resultadosFinais.push({

    json: {

      ...origem,

      projeto: CONFIG.projeto,

      validador_editorial: {

        versao: CONFIG.versao,

        status,

        validacao_estrutural_ok:
          validacaoOK,

        titulo_original:
          tituloOriginal,

        candidatos_recebidos:
          candidatosOriginais.length,

        candidatos_analisados:
          correspondencias.length,

        total_mesmo_acontecimento:
          totalMesmoEvento,

        total_correspondencias_fortes:
          totalFortes,

        total_incertos:
          totalIncertos,

        limiar_correspondencia:
          CONFIG.limiarCorrespondencia,

        risco_editorial_elevado:
          riscoElevado,

        correspondencias,

        alertas: [
          ...lista(
            analiseGemini.alertas_editoriais
          ),
          ...alertas
        ],

        erros

      },

      verificacao: {

        ...objeto(origem.verificacao),

        status:
          "AGUARDANDO_VERIFICACAO_DAS_FONTES",

        fontes_independentes_verificadas:
          0,

        confirmacao_oficial: false,

        fatos_verificados: [],

        revisao_humana_realizada: false

      },

      seguranca: {

        ...objeto(origem.seguranca),

        aprovado_para_producao: false,

        aprovado_para_publicacao: false,

        motivo_bloqueio:
          "FONTES_ORIGINAIS_NAO_VERIFICADAS"

      },

      proxima_etapa:
        validacaoOK
          ? "VERIFICAR_FONTES_ORIGINAIS"
          : "CORRIGIR_ERROS_DE_VALIDACAO"

    },

    pairedItem: {
      item: indiceNoticia
    }

  });

}


// ============================================================
// 17. RETORNAR RESULTADOS
// ============================================================

return resultadosFinais;

/**
 * ============================================================
 * VICESCOPE | PREPARADOR DE FONTES V1.2
 * ============================================================
 *
 * n8n: Run Once for All Items
 *
 * CORREÇÕES:
 * - Não depende da classe global URL
